<script setup>
import { ref, computed, watch, onMounted, onUnmounted, nextTick } from 'vue'
import { LayoutDashboard, Calculator, Layers3, Printer, Settings2, Plus, Trash2, ExternalLink, Download, Upload, Box, Zap, Clock3, TrendingUp, PoundSterling, ChevronRight, Info, Check, X, Sun, Moon, Monitor, ChevronLeft, Menu, Sparkles, HelpCircle, Package, BarChart3, ShoppingBag, ChevronDown, LogOut, Users, UserRound, ShieldCheck } from 'lucide-vue-next'

const initial = { settings:{currency:'GBP',siteTitle:'PrintQuote',siteSubtitle:'PRINT COST STUDIO',logo:'',accent:'#5277e8',background:'#f3f7ff',darkBackground:'#1b283d',themeMode:'auto',energyRate:0.28,labourRate:12,defaultMargin:30,onboardingCompleted:false,features:{dashboard:true,quotes:true,products:true,filaments:true,printers:true,sales:true,inventory:false,printHistory:false,advancedCosting:true,forecasting:true}}, filaments:[], printers:[], quotes:[], products:[], sales:[], spools:[], inventoryMovements:[], calculations:[], printRuns:[] }
function clone(x){return JSON.parse(JSON.stringify(x))}
const state=ref(clone(initial))
const ready=ref(false), syncStatus=ref('Connecting…'), syncError=ref(false)
const systemDark=ref(window.matchMedia('(prefers-color-scheme: dark)').matches)
const media=window.matchMedia('(prefers-color-scheme: dark)')
const mediaListener=e=>{systemDark.value=e.matches}
const isDark=computed(()=>state.value.settings.themeMode==='dark'||(state.value.settings.themeMode==='auto'&&systemDark.value))
const theme=computed(()=>({ '--accent':state.value.settings.accent||'#6478f5','--surface':isDark.value?(state.value.settings.darkBackground||'#101827'):(state.value.settings.background||'#f7f9ff'), }))
function reloadApplication(){window.location.reload()}
function cycleTheme(){if(!canEdit.value)return;const modes=['auto','light','dark'];state.value.settings.themeMode=modes[(modes.indexOf(state.value.settings.themeMode)+1)%3]}
const themeLabel=computed(()=>({auto:'Auto theme',light:'Light theme',dark:'Dark theme'})[state.value.settings.themeMode]||'Auto theme')
let timer=null, saving=false, dirty=false, generation=0
const authUser=ref(null),authReady=ref(false),authToken=ref(localStorage.getItem('pq_token')||sessionStorage.getItem('pq_token')||'')
const loginDraft=ref({username:'',password:'',remember:false}),loginError=ref(''),loginBusy=ref(false)
const accountMenu=ref(false),adminUsers=ref([]),adminError=ref(''),adminDraft=ref({username:'',firstName:'',lastName:'',password:'',email:'',role:'user'})
const editingUser=ref(null),userEditBusy=ref(false)
function beginUserEdit(u){editingUser.value={id:u.id,username:u.username,firstName:u.firstName,lastName:u.lastName,email:u.email||'',role:u.role}}
async function saveUserEdit(){adminError.value='';userEditBusy.value=true;try{await api('/api/admin/users/'+editingUser.value.id,{method:'PATCH',body:JSON.stringify(editingUser.value)});editingUser.value=null;await loadUsers();toast('Account updated and user notified by email')}catch(e){adminError.value=e.message}finally{userEditBusy.value=false}}
async function resetUserPassword(u){if(!confirm('Generate a new password and email it to '+u.email+'? Their existing sessions will be revoked.'))return;adminError.value='';try{await api('/api/admin/users/'+u.id+'/reset-password',{method:'POST'});toast('Temporary password emailed to user')}catch(e){adminError.value=e.message}}
const activityLog=ref([]), activityError=ref('')
async function loadActivity(){try{activityLog.value=(await api('/api/admin/activity')).events||[];activityError.value=''}catch(e){activityError.value=e.message}}
async function setUserRole(user,role){try{await api('/api/admin/users/'+user.id+'/role',{method:'PATCH',body:JSON.stringify({role})});await loadUsers();await loadActivity()}catch(e){adminError.value=e.message}}
const releaseData=ref({current:'2.2.2',releases:[],schedules:[],showNotice:false,reminderLevel:'major',autoUpdate:false}),releaseError=ref(''),releaseWhen=ref(''),releaseTarget=ref(''),updatePopup=ref(false)
async function loadReleases(){if(authUser.value?.role!=='admin')return;try{releaseData.value=await api('/api/admin/releases');releaseTarget.value ||= releaseData.value.releases[0]?.version||'';updatePopup.value=releaseData.value.showNotice;releaseError.value=''}catch(e){releaseError.value=e.message}}
const updateSettingsBusy=ref(false),updatedPopup=ref(false),updatedVersion=ref('')
async function saveUpdatePreferences(){updateSettingsBusy.value=true;releaseError.value='';try{await api('/api/admin/update-preferences',{method:'PATCH',body:JSON.stringify({reminderLevel:releaseData.value.reminderLevel,autoUpdate:releaseData.value.autoUpdate})});await loadReleases();toast('Update preferences saved')}catch(e){releaseError.value=e.message}finally{updateSettingsBusy.value=false}}
let versionPoll=null
async function checkRunningVersion(){if(!authUser.value)return;try{const data=await api('/api/version');const previous=localStorage.getItem('pq_seen_version');if(previous&&previous!==data.current){updatedVersion.value=data.current;updatedPopup.value=true}localStorage.setItem('pq_seen_version',data.current)}catch{}}
async function scheduleRelease(){try{if(!releaseWhen.value)throw Error('Select a date and time');await api('/api/admin/releases/schedule',{method:'POST',body:JSON.stringify({version:releaseTarget.value,executeAt:new Date(releaseWhen.value).toISOString()})});await loadReleases();toast('Deployment scheduled')}catch(e){releaseError.value=e.message}}
async function cancelRelease(id){try{await api('/api/admin/releases/schedule/'+id,{method:'DELETE'});await loadReleases()}catch(e){releaseError.value=e.message}}
async function dismissRelease(){try{await api('/api/admin/releases/dismiss',{method:'POST',body:JSON.stringify({version:releaseData.value.latest})});updatePopup.value=false}catch(e){releaseError.value=e.message}}
const passwordDraft=ref({currentPassword:'',newPassword:''}),passwordError=ref('')
const initials=computed(()=>[authUser.value?.firstName,authUser.value?.lastName].map(x=>String(x||'').trim().slice(0,1)).join('').toUpperCase()||'U')
function storeToken(token,remember){authToken.value=token;localStorage.removeItem('pq_token');sessionStorage.removeItem('pq_token');(remember?localStorage:sessionStorage).setItem('pq_token',token)}
function logoutLocal(){authToken.value='';authUser.value=null;ready.value=false;authReady.value=true;accountMenu.value=false;localStorage.removeItem('pq_token');sessionStorage.removeItem('pq_token');clearTimeout(timer);dirty=false}
async function api(url,options={}){if(options.method==='PUT' && ['viewer'].includes(authUser.value?.role))throw Error('Read-only account');const res=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(authToken.value?{Authorization:'Bearer '+authToken.value}:{}),...options.headers}});if(res.status===401&&url!=='/api/auth/login'){logoutLocal();throw Error('Session expired')}const body=await res.json().catch(()=>({}));if(!res.ok)throw Error(body.error||`Server returned ${res.status}`);return body}
async function checkAuth(){try{if(authToken.value){const data=await api('/api/auth/me');authUser.value=data.user;await refresh();await loadReleases();await checkRunningVersion()}}catch(e){logoutLocal()}finally{authReady.value=true}}
async function login(){loginError.value='';loginBusy.value=true;try{const data=await api('/api/auth/login',{method:'POST',body:JSON.stringify(loginDraft.value)});storeToken(data.token,loginDraft.value.remember);authUser.value=data.user;loginDraft.value.password='';await refresh();await loadReleases();await checkRunningVersion()}catch(e){loginError.value=e.message}finally{loginBusy.value=false}}
async function logout(){try{await api('/api/auth/logout',{method:'POST'})}catch{}logoutLocal()}
async function loadUsers(){adminError.value='';try{adminUsers.value=(await api('/api/admin/users')).users}catch(e){adminError.value=e.message}}
async function createUser(){adminError.value='';try{await api('/api/admin/users',{method:'POST',body:JSON.stringify(adminDraft.value)});adminDraft.value={username:'',firstName:'',lastName:'',password:'',email:'',role:'user'};await loadUsers();toast('User created')}catch(e){adminError.value=e.message}}
async function deleteUser(user){if(!confirm('Delete '+user.username+'? Their active sessions will be revoked.'))return;try{await api('/api/admin/users/'+user.id,{method:'DELETE'});await loadUsers()}catch(e){adminError.value=e.message}}
async function changePassword(){passwordError.value='';try{await api('/api/auth/password',{method:'POST',body:JSON.stringify(passwordDraft.value)});passwordDraft.value={currentPassword:'',newPassword:''};authUser.value={...authUser.value,mustChangePassword:false};toast('Password updated. Please sign in again.');logoutLocal()}catch(e){passwordError.value=e.message}}
async function refresh(){try{const data=await api('/api/state');if(!Array.isArray(data.filaments)||!Array.isArray(data.printers))throw Error('Invalid database state');state.value={...clone(initial),...data,products:Array.isArray(data.products)?data.products:[],sales:Array.isArray(data.sales)?data.sales:[],spools:Array.isArray(data.spools)?data.spools:[],inventoryMovements:Array.isArray(data.inventoryMovements)?data.inventoryMovements:[],calculations:Array.isArray(data.calculations)?data.calculations:[],printRuns:Array.isArray(data.printRuns)?data.printRuns:[],settings:{...initial.settings,...data.settings,onboardingCompleted:data.settings?.onboardingCompleted ?? true,features:{...initial.settings.features,...data.settings?.features}}};ready.value=true; if(!hasCompletedTour()) startTour();syncError.value=false;syncStatus.value='Database connected'}catch(e){syncError.value=true;syncStatus.value='Database unavailable';console.error(e)}}
async function flush(){if(!ready.value||saving)return;saving=true;while(dirty){dirty=false;const payload=JSON.stringify(state.value);syncStatus.value='Saving…';try{await api('/api/state',{method:'PUT',body:payload});syncStatus.value='Saved to database';syncError.value=false}catch(e){dirty=true;syncError.value=true;syncStatus.value='Save failed — retrying';console.error(e);break}}saving=false;if(dirty){clearTimeout(timer);timer=setTimeout(flush,3000)}}
watch(state,()=>{if(!ready.value||!canEdit.value)return;dirty=true;syncStatus.value='Unsaved changes';clearTimeout(timer);timer=setTimeout(flush,650)},{deep:true})
onMounted(()=>{versionPoll=setInterval(checkRunningVersion,60000);media.addEventListener('change',mediaListener);window.addEventListener('resize',positionTour);window.addEventListener('scroll',positionTour,true);checkAuth()})
onUnmounted(()=>{clearInterval(versionPoll);media.removeEventListener('change',mediaListener);window.removeEventListener('resize',positionTour);window.removeEventListener('scroll',positionTour,true);clearTimeout(timer)})
const logoInput=ref(null)
function uploadLogo(e){const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('image/')){toast('Please select an image');return}if(f.size>1024*1024){toast('Logo must be smaller than 1 MB');return}const reader=new FileReader();reader.onload=()=>{state.value.settings.logo=String(reader.result);toast('Logo updated')};reader.readAsDataURL(f);e.target.value=''}

const page=ref('calculator'), mobileMenu=ref(false), sidebarCollapsed=ref(false), notification=ref('')
function toast(t){notification.value=t;setTimeout(()=>notification.value='',3000)}
const uid=()=>Math.random().toString(36).slice(2,10)
const money=v=>new Intl.NumberFormat('en-GB',{style:'currency',currency:state.value.settings.currency||'GBP'}).format(Number(v)||0)
const num=(v)=>Math.max(0,Number(v)||0)
const quote=ref({name:'',filamentId:'',printerId:'',grams:120,hours:4,minutes:30,quantity:1,margin:30,extraCost:0,setupOverride:false})
const filament=computed(()=>state.value.filaments.find(f=>f.id===quote.value.filamentId))
const materialRows=q=>Array.isArray(q.filamentUses)&&q.filamentUses.length?q.filamentUses:[{filamentId:q.filamentId,grams:q.grams}]
const materialCost=q=>materialRows(q).reduce((sum,row)=>sum+num(row.grams)/1000*num(state.value.filaments.find(f=>f.id===row.filamentId)?.price),0)
function addQuoteFilament(){if(!quote.value.filamentUses?.length)quote.value.filamentUses=[{filamentId:quote.value.filamentId,grams:quote.value.grams}];quote.value.filamentUses.push({filamentId:state.value.filaments[0]?.id||'',grams:0})}
function removeQuoteFilament(i){quote.value.filamentUses.splice(i,1);if(!quote.value.filamentUses.length)quote.value.filamentUses=null}
const printerCatalog=ref([]),catalogError=ref(''),catalogLoading=ref(false)
const printerBrands=computed(()=>[...new Set(printerCatalog.value.map(x=>x.brand))].sort())
const printerSeries=computed(()=>[...new Set(printerCatalog.value.filter(x=>x.brand===editingPrinter.value?.brand).map(x=>x.series))].sort())
const printerModels=computed(()=>printerCatalog.value.filter(x=>x.brand===editingPrinter.value?.brand&&x.series===editingPrinter.value?.series).map(x=>x.model).sort())
async function loadPrinterCatalog(){catalogLoading.value=true;try{const response=await fetch('/api/printer-catalog');if(!response.ok)throw Error('Catalogue unavailable');const data=await response.json();printerCatalog.value=Array.isArray(data)?data:[];catalogError.value=''}catch(e){catalogError.value=e.message}finally{catalogLoading.value=false}}
function selectPrinterModel(){const found=printerCatalog.value.find(x=>x.brand===editingPrinter.value.brand&&x.series===editingPrinter.value.series&&x.model===editingPrinter.value.model);if(found?.technology)editingPrinter.value.technology=found.technology}

const printer=computed(()=>state.value.printers.find(p=>p.id===quote.value.printerId))
const calc=computed(()=>{const q=quote.value,p=printer.value;const qty=Math.max(1,Math.floor(Number(q.quantity)||1));const hours=num(q.hours)+num(q.minutes)/60;const material=materialCost(q)*qty;const energy=hours*num(p?.power)/1000*num(state.value.settings.energyRate)*qty;const labour=(num(p?.setupMinutes)+num(p?.postMinutes)*qty)/60*num(state.value.settings.labourRate);const overhead=hours*num(p?.overheadRate)*qty;const extras=num(q.extraCost)*qty;const cost=material+energy+labour+overhead+extras;const margin=Math.min(99.9,num(q.margin));const price=cost/(1-margin/100);const profit=price-cost;return {qty,hours,material,energy,labour,overhead,extras,cost,price,profit,margin,markup:cost?profit/cost*100:0,unit:price/qty}})
const saveMenu=ref(false), saveDropdownRef=ref(null), saleProduct=ref(null), saleDraft=ref({quantity:1,unitPrice:0,date:new Date().toISOString().slice(0,10),note:''})
const extraItems=ref([])
function unitCostFor(p){
 const f=state.value.filaments.find(x=>x.id===p.filamentId),r=state.value.printers.find(x=>x.id===p.printerId)
 if(!r||!materialRows(p).every(row=>state.value.filaments.some(f=>f.id===row.filamentId)))return null
 const hours=num(p.hours)+num(p.minutes)/60
 return materialCost(p)+hours*num(r.power)/1000*num(state.value.settings.energyRate)+(num(r.setupMinutes)+num(r.postMinutes))/60*num(state.value.settings.labourRate)+hours*num(r.overheadRate)+num(p.extraCost)
}
function variantList(p){return Array.isArray(p.variants)&&p.variants.length?p.variants:[{id:'base',name:'Standard',filamentId:p.filamentId,printerId:p.printerId,grams:p.grams,hours:p.hours,minutes:p.minutes,price:p.price,extraCost:p.extraCost||0,materials:p.materials||[],filamentUses:p.filamentUses||null}]}
function costOfVariant(p,v){const base=unitCostFor({...p,...v});if(base===null)return null;const materials=(v.materials||[]).reduce((sum,m)=>sum+num(m.quantity)*num(m.unitCost),0);return base+materials+num(v.packagingCost)+num(v.maintenanceCost)}
const productCost=p=>costOfVariant(p,variantList(p)[0])
const selectedVariantId=ref(''), variantFor=(p,id)=>variantList(p).find(v=>v.id===id)||variantList(p)[0]
const saleDeductStock=ref(false),saleSpoolId=ref('')
const inventorySpools=computed(()=>state.value.spools||[])
const spoolDraft=ref({filamentId:'',label:'',originalGrams:1000,remainingGrams:1000,purchasePrice:20,location:''}), inventoryQuantity=ref(0),inventorySpool=ref(null),inventoryReason=ref('Adjustment')
function addSpool(){const d=spoolDraft.value;if(!d.filamentId||!d.label.trim()||num(d.originalGrams)<=0){toast('Select filament, name and spool weight');return}state.value.spools.push({...clone(d),id:uid(),originalGrams:num(d.originalGrams),remainingGrams:num(d.remainingGrams)});spoolDraft.value={filamentId:'',label:'',originalGrams:1000,remainingGrams:1000,purchasePrice:20,location:''};toast('Spool added')}
function adjustSpool(){const sp=inventorySpool.value;if(!sp)return;const delta=Number(inventoryQuantity.value);if(!Number.isFinite(delta)||delta===0||sp.remainingGrams+delta<0){toast('Invalid stock adjustment');return}const real=state.value.spools.find(x=>x.id===sp.id);if(!real)return;real.remainingGrams+=delta;state.value.inventoryMovements.unshift({id:uid(),spoolId:sp.id,delta,reason:inventoryReason.value,date:new Date().toISOString()});inventorySpool.value=null;inventoryQuantity.value=0;toast('Stock adjusted')}
function addVariant(){if(!editingProduct.value.variants)editingProduct.value.variants=[];const p=editingProduct.value;const base=variantList(p)[0];p.variants.push({...clone(base),id:uid(),name:'New variant',materials:clone(base.materials||[])})}
function addMaterial(v){if(!v.materials)v.materials=[];v.materials.push({id:uid(),name:'',quantity:1,unitCost:0})}
const productForecast=p=>{const months=Array.from({length:3},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i-1);return d.toISOString().slice(0,7)}).reverse();const values=months.map(m=>productSales(p).filter(x=>x.date.startsWith(m)).reduce((a,x)=>a+num(x.quantity),0));const total=values.reduce((a,b)=>a+b,0);return {units:Math.round(values[0]*.2+values[1]*.3+values[2]*.5),confidence:total>=30?'Medium':total>=8?'Low':'Insufficient data'}}
const dateWindow=ref('all');const filteredSales=computed(()=>{if(dateWindow.value==='all')return state.value.sales;const after=new Date();after.setDate(after.getDate()-Number(dateWindow.value));return state.value.sales.filter(s=>new Date(s.date+'T12:00:00')>=after)})
const filteredSummary=computed(()=>({units:filteredSales.value.reduce((a,s)=>a+num(s.quantity),0),revenue:filteredSales.value.reduce((a,s)=>a+num(s.quantity)*num(s.unitPrice),0),profit:filteredSales.value.reduce((a,s)=>a+num(s.quantity)*(num(s.unitPrice)-num(s.unitCost)),0)}))
const productMargin=p=>{const cost=productCost(p);return cost===null||!num(p.price)?null:(num(p.price)-cost)/num(p.price)*100}
function addQuoteProduct(p){const v=variantFor(p,selectedVariantId.value);const cost=costOfVariant(p,v);if(cost===null){toast('Assign a valid filament and printer to this product');return}extraItems.value.push({id:uid(),productId:p.id,variantId:v.id,name:p.name+(v.id==='base'?'':' — '+v.name),quantity:1,unitPrice:num(v.price),unitCost:cost});page.value='calculator';toast('Product added to quote')}
function addSelectedProduct(){const select=document.getElementById('quote-product-select');const p=state.value.products.find(x=>x.id===select?.value);if(!p){toast('Select a product first');return}addQuoteProduct(p);select.value=''}
function removeSale(id){if(!confirm('Delete this recorded sale?'))return;state.value.sales=state.value.sales.filter(s=>s.id!==id)}
function removeQuoteItem(id){extraItems.value=extraItems.value.filter(x=>x.id!==id)}
const extraTotal=computed(()=>extraItems.value.reduce((sum,x)=>sum+num(x.unitPrice)*Math.max(1,Math.floor(num(x.quantity))),0))
const extraCostTotal=computed(()=>extraItems.value.reduce((sum,x)=>sum+num(x.unitCost)*Math.max(1,Math.floor(num(x.quantity))),0))
const quoteGrandTotal=computed(()=>calc.value.price+extraTotal.value)
const quoteGrandCost=computed(()=>calc.value.cost+extraCostTotal.value)
const defaultSaveLabel=computed(()=>features.value.quotes?'Save quote':'Save calculation')
function closeSaveMenu(){saveMenu.value=false}
function onSaveMenuPointerDown(event){
  if(saveMenu.value && saveDropdownRef.value && !saveDropdownRef.value.contains(event.target))closeSaveMenu()
}
function onSaveMenuKeyDown(event){if(event.key==='Escape' && saveMenu.value){closeSaveMenu();saveDropdownRef.value?.querySelector('button')?.focus()}}
function productFromCalculator(){if(!printer.value||!materialRows(quote.value).every(row=>state.value.filaments.some(f=>f.id===row.filamentId))){toast('Select a printer and filaments first');return}newProduct();editingProduct.value.name=quote.value.name||'';editingProduct.value.price=Number(calc.value.unit.toFixed(2));saveMenu.value=false}
function beginSale(p){saleDeductStock.value=false;saleSpoolId.value='';saleProduct.value=p;selectedVariantId.value=variantList(p)[0].id;saleDraft.value={quantity:1,unitPrice:num(variantList(p)[0].price),date:new Date().toISOString().slice(0,10),note:''}}
function recordSale(){if(!saleProduct.value)return;const quantity=Math.floor(Number(saleDraft.value.quantity));const price=Number(saleDraft.value.unitPrice);if(!Number.isInteger(quantity)||quantity<1||!Number.isFinite(price)||price<0||!/^\d{4}-\d{2}-\d{2}$/.test(saleDraft.value.date)){toast('Enter a valid quantity, price and date');return}
 const variant=variantFor(saleProduct.value,selectedVariantId.value);const cost=costOfVariant(saleProduct.value,variant);const grams=num(variant.grams)*quantity;state.value.sales.unshift({variantId:variant.id,variantName:variant.name,id:uid(),productId:saleProduct.value.id,productName:saleProduct.value.name,quantity,unitPrice:price,unitCost:cost,date:saleDraft.value.date,note:saleDraft.value.note||''});saleProduct.value=null;toast('Sale recorded')}
const printingProduct=ref(null),printVariantId=ref(''),printCount=ref(1),printSpoolSelections=ref({})
const printDraft=ref({success:true,actualHours:0,actualMinutes:0,note:'',deductStock:true}),printActualRows=ref({})
const printHistoryFilter=ref('all')
const printHistoryRows=computed(()=>[...(state.value.printRuns||[])].filter(r=>printHistoryFilter.value==='all'||(printHistoryFilter.value==='failed'?!r.success:r.success)).sort((a,b)=>String(b.date).localeCompare(String(a.date))))
const printStats=computed(()=>{const runs=state.value.printRuns||[];const estimated=runs.reduce((a,r)=>a+num(r.estimatedCost),0);const actual=runs.reduce((a,r)=>a+num(r.actualCost),0);return {runs:runs.length,failed:runs.filter(r=>!r.success).length,estimated,actual,variance:actual-estimated,materialWaste:runs.filter(r=>!r.success).reduce((a,r)=>a+num(r.actualGrams),0)}})
function resetActualPrint(){
  if(!printingProduct.value)return
  const v=variantFor(printingProduct.value,printVariantId.value)
  printActualRows.value=Object.fromEntries(materialRows(v).filter(r=>r.filamentId).map(r=>[r.filamentId,num(r.grams)*Math.max(1,Math.floor(num(printCount.value)))]))
  printDraft.value={success:true,actualHours:Math.floor((num(v.hours)*60+num(v.minutes))*Math.max(1,Math.floor(num(printCount.value)))/60),actualMinutes:Math.round((num(v.hours)*60+num(v.minutes))*Math.max(1,Math.floor(num(printCount.value))))%60,note:'',deductStock:features.value.inventory}
}
function removePrintRun(run){
 if(!canEdit.value||!confirm('Delete this print history entry? Any recorded stock consumption will remain in inventory history.'))return
 state.value.printRuns=state.value.printRuns.filter(r=>r.id!==run.id);toast('Print history entry removed')
}
function recordPrintV24(){
 if(!canEdit.value||!printingProduct.value)return
 const quantity=Number(printCount.value),hours=Number(printDraft.value.actualHours),minutes=Number(printDraft.value.actualMinutes)
 if(!Number.isInteger(quantity)||quantity<1||quantity>100000||!Number.isFinite(hours)||hours<0||!Number.isFinite(minutes)||minutes<0||minutes>=60){toast('Enter valid print quantity and actual duration');return}
 const product=printingProduct.value,v=variantFor(product,printVariantId.value),rows=materialRows(v).filter(r=>r.filamentId)
 if(!rows.length){toast('Assign filament to this variant first');return}
 const requirements=[]
 for(const row of rows){const grams=Number(printActualRows.value[row.filamentId]);if(!Number.isFinite(grams)||grams<0){toast('Enter valid actual filament usage');return}requirements.push({filamentId:row.filamentId,grams})}
 const consumption=new Map();for(const row of requirements)consumption.set(row.filamentId,(consumption.get(row.filamentId)||0)+row.grams)
 const adjustments=[]
 if(printDraft.value.deductStock&&features.value.inventory){for(const [filamentId,grams] of consumption){if(grams===0)continue;const sp=state.value.spools.find(x=>x.id===printSpoolSelections.value[filamentId]);if(!sp||sp.filamentId!==filamentId||num(sp.remainingGrams)<grams){toast('Choose a matching spool with enough stock for each material');return}adjustments.push({sp,grams})}}
 const estimatedHours=(num(v.hours)+num(v.minutes)/60)*quantity
 const actualHours=hours+minutes/60
 const printerProfile=state.value.printers.find(p=>p.id===v.printerId)
 const estimatedCost=(costOfVariant(product,v)||0)*quantity
 const actualMaterial=[...consumption].reduce((a,[id,grams])=>a+grams/1000*num(state.value.filaments.find(f=>f.id===id)?.price),0)
 const actualEnergy=actualHours*num(printerProfile?.power)/1000*num(state.value.settings.energyRate)
 const actualLabour=(num(printerProfile?.setupMinutes)+num(printerProfile?.postMinutes)*quantity)/60*num(state.value.settings.labourRate)
 const actualOverhead=actualHours*num(printerProfile?.overheadRate)
 const otherCosts=quantity*(num(v.extraCost)+num(v.packagingCost)+num(v.maintenanceCost)+(v.materials||[]).reduce((a,m)=>a+num(m.quantity)*num(m.unitCost),0))
 const actualCost=actualMaterial+actualEnergy+actualLabour+actualOverhead+otherCosts
 const date=new Date().toISOString(),id=uid()
 for(const {sp,grams} of adjustments){sp.remainingGrams-=grams;state.value.inventoryMovements.unshift({id:uid(),printRunId:id,spoolId:sp.id,delta:-grams,reason:'Print '+(printDraft.value.success?'completed':'failed')+': '+product.name+' / '+v.name+' × '+quantity,date})}
 state.value.printRuns.unshift({id,date,productId:product.id,productName:product.name,variantId:v.id,variantName:v.name,printerId:v.printerId,printerName:printerProfile?.name||'Unknown',quantity,success:printDraft.value.success,note:printDraft.value.note||'',estimatedHours,actualHours,estimatedGrams:rows.reduce((a,r)=>a+num(r.grams)*quantity,0),actualGrams:[...consumption.values()].reduce((a,g)=>a+g,0),estimatedCost,actualCost,materials:[...consumption].map(([filamentId,grams])=>({filamentId,grams,name:state.value.filaments.find(f=>f.id===filamentId)?.name||'Unknown'})),stockDeducted:adjustments.length>0})
 printingProduct.value=null;toast('Print run recorded'+(adjustments.length?' and actual filament deducted':''))
}

const printRequirements=computed(()=>{if(!printingProduct.value)return [];const v=variantFor(printingProduct.value,printVariantId.value);const combined=new Map();for(const row of materialRows(v)){if(!row.filamentId||num(row.grams)<=0)continue;combined.set(row.filamentId,(combined.get(row.filamentId)||0)+num(row.grams)*Math.max(1,Math.floor(num(printCount.value))))}return [...combined].map(([filamentId,grams])=>({filamentId,grams,name:state.value.filaments.find(f=>f.id===filamentId)?.name||'Unknown'}))})
function beginPrint(p){printingProduct.value=p;printVariantId.value=variantList(p)[0].id;printCount.value=1;printSpoolSelections.value={};resetActualPrint()}
function recordPrint(){if(!canEdit.value)return;const quantity=Number(printCount.value);if(!Number.isInteger(quantity)||quantity<1||quantity>100000){toast('Enter a valid number printed');return}if(!printRequirements.value.length){toast('Set filament quantities for this product first');return}const adjustments=[];const used=new Set();for(const req of printRequirements.value){const sp=state.value.spools.find(s=>s.id===printSpoolSelections.value[req.filamentId]);if(!sp||sp.filamentId!==req.filamentId||used.has(sp.id)){toast('Choose a matching spool for every filament');return}if(num(sp.remainingGrams)<req.grams){toast('Not enough '+req.name+' on '+sp.label);return}used.add(sp.id);adjustments.push({sp,grams:req.grams})}const name=printingProduct.value.name;const variant=variantFor(printingProduct.value,printVariantId.value);for(const {sp,grams} of adjustments){sp.remainingGrams-=grams;state.value.inventoryMovements.unshift({id:uid(),spoolId:sp.id,delta:-grams,reason:'Printed: '+name+' / '+variant.name+' × '+quantity,date:new Date().toISOString()})}printingProduct.value=null;toast('Print recorded; filament stock deducted')}
const salesSummary=computed(()=>{const sales=state.value.sales||[];return {count:sales.reduce((a,x)=>a+num(x.quantity),0),revenue:sales.reduce((a,x)=>a+num(x.quantity)*num(x.unitPrice),0),profit:sales.reduce((a,x)=>a+num(x.quantity)*(num(x.unitPrice)-num(x.unitCost)),0)}})
const productSales=p=>state.value.sales.filter(x=>x.productId===p.id)
const productUnits=p=>productSales(p).reduce((a,x)=>a+num(x.quantity),0)
const ranking=computed(()=>state.value.products.map(p=>({...p,units:productUnits(p),revenue:productSales(p).reduce((a,x)=>a+num(x.quantity)*num(x.unitPrice),0)})).sort((a,b)=>b.units-a.units))
const recentSales=computed(()=>[...filteredSales.value].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6))
const monthlyTrend=computed(()=>{const today=new Date();const months=Array.from({length:6},(_,i)=>{const d=new Date(today.getFullYear(),today.getMonth()-5+i,1);return {key:d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'),label:d.toLocaleDateString('en-GB',{month:'short'}),revenue:0,units:0}});for(const sale of state.value.sales){const m=months.find(x=>x.key===String(sale.date).slice(0,7));if(m){m.revenue+=num(sale.unitPrice)*num(sale.quantity);m.units+=num(sale.quantity)}}return months})
const salesAnalytics=computed(()=>{const sales=filteredSales.value;const byProduct=new Map();for(const x of sales){const k=x.productId||x.productName;const v=byProduct.get(k)||{name:x.productName,units:0,revenue:0,profit:0};v.units+=num(x.quantity);v.revenue+=num(x.quantity)*num(x.unitPrice);v.profit+=num(x.quantity)*(num(x.unitPrice)-num(x.unitCost));byProduct.set(k,v)}const rows=[...byProduct.values()].sort((a,b)=>b.profit-a.profit);const revenue=rows.reduce((a,x)=>a+x.revenue,0),profit=rows.reduce((a,x)=>a+x.profit,0);return {rows,revenue,profit,margin:revenue?100*profit/revenue:0,averageOrder:sales.length?revenue/sales.length:0,topShare:revenue&&rows.length?rows[0].revenue/revenue*100:0}})
const trendMax=computed(()=>Math.max(1,...monthlyTrend.value.map(x=>x.revenue)))
const forecast=computed(()=>{const past=monthlyTrend.value.slice(0,5);const nonzero=past.filter(x=>x.units>0);if(nonzero.length<2)return null;const avg=nonzero.reduce((a,x)=>a+x.units,0)/nonzero.length;const recent=monthlyTrend.value.slice(-3,-1).reduce((a,x)=>a+x.units,0)/2;return Math.max(0,Math.round((avg+recent)/2))})
const forecastDetails=computed(()=>{const months=monthlyTrend.value.slice(0,-1);const observed=months.filter(m=>m.units>0);if(observed.length<2)return null;const recent=months.slice(-3);const weights=[1,2,3];const prediction=Math.max(0,Math.round(recent.reduce((sum,m,i)=>sum+m.units*weights[i],0)/6));const mean=observed.reduce((a,m)=>a+m.units,0)/observed.length;const variance=observed.reduce((a,m)=>a+(m.units-mean)**2,0)/observed.length;const variability=mean?Math.sqrt(variance)/mean:1;return {prediction,confidence:observed.length>=5&&variability<.3?'Moderate':'Low',months:observed.length,range:[Math.max(0,Math.floor(prediction*(1-Math.min(.7,variability)))),Math.ceil(prediction*(1+Math.min(.7,variability)))]}})
const editingFilament=ref(null),editingPrinter=ref(null)
function newFilament(){editingFilament.value={id:uid(),name:'',brand:'',material:'PLA',colour:'',price:20,url:'',stockGrams:0,lowStockGrams:150}}
function editFilament(f){editingFilament.value=clone(f)}
function saveFilament(){const f=editingFilament.value;if(!f.name.trim()){toast('Please enter a filament name');return}if(f.url && !/^https?:\/\//i.test(f.url)){toast('Purchase link must start with http:// or https://');return}f.price=num(f.price);f.stockGrams=num(f.stockGrams);f.lowStockGrams=num(f.lowStockGrams);const idx=state.value.filaments.findIndex(x=>x.id===f.id);if(idx<0)state.value.filaments.push(f);else state.value.filaments[idx]=f;if(!quote.value.filamentId)quote.value.filamentId=f.id;editingFilament.value=null;toast('Filament saved')}
function removeFilament(id){if(!confirm('Delete this filament?'))return;state.value.filaments=state.value.filaments.filter(f=>f.id!==id);if(quote.value.filamentId===id)quote.value.filamentId=state.value.filaments[0]?.id||''}
function newPrinter(){editingPrinter.value={id:uid(),name:'',brand:'',series:'',model:'',technology:'FDM',power:100,setupMinutes:10,postMinutes:10,overheadRate:0.25};loadPrinterCatalog()}
function editPrinter(p){editingPrinter.value=clone(p);loadPrinterCatalog()}
function savePrinter(){const p=editingPrinter.value;if(!p.name.trim()){toast('Please enter a printer name');return}for(const k of ['power','setupMinutes','postMinutes','overheadRate'])p[k]=num(p[k]);const idx=state.value.printers.findIndex(x=>x.id===p.id);if(idx<0)state.value.printers.push(p);else state.value.printers[idx]=p;if(!quote.value.printerId)quote.value.printerId=p.id;editingPrinter.value=null;toast('Printer saved')}
function removePrinter(id){if(!confirm('Delete this printer profile?'))return;state.value.printers=state.value.printers.filter(p=>p.id!==id);if(quote.value.printerId===id)quote.value.printerId=state.value.printers[0]?.id||''}
const calculationHistory=computed(()=>[...(state.value.calculations||[])].sort((a,b)=>String(b.date).localeCompare(String(a.date))))
const historySearch=ref(''),showCalculationHistory=ref(false)
const filteredCalculationHistory=computed(()=>calculationHistory.value.filter(h=>(h.name+' '+(h.filament||'')+' '+(h.printer||'')).toLowerCase().includes(historySearch.value.toLowerCase())))
function saveCalculation(){
  if(!canEdit.value)return
  if(!printer.value||!materialRows(quote.value).every(row=>state.value.filaments.some(f=>f.id===row.filamentId))){toast('Choose a printer and valid filaments before saving');return}
  const name=(quote.value.name||'').trim()||'Untitled calculation'
  state.value.calculations.unshift({
    id:uid(),name,date:new Date().toISOString(),
    details:clone(quote.value),filament:materialRows(quote.value).map(row=>state.value.filaments.find(f=>f.id===row.filamentId)?.name||'Unknown').join(', '),printer:printer.value.name,
    result:clone(calc.value)
  })
  toast('Calculation saved to history')
}
function loadCalculation(h){
  quote.value={...quote.value,...clone(h.details)}
  extraItems.value=[]
  page.value='calculator'
  toast('Calculation restored — current material and printer prices are applied')
}
function removeCalculation(id){
  if(!canEdit.value)return
  if(!confirm('Delete this saved calculation?'))return
  state.value.calculations=state.value.calculations.filter(h=>h.id!==id)
  toast('Calculation removed')
}
function saveQuote(){if(!printer.value||!materialRows(quote.value).every(row=>state.value.filaments.some(f=>f.id===row.filamentId))){toast('Add a printer and valid filaments first');return}state.value.quotes.unshift({id:uid(),name:quote.value.name.trim()||'Untitled print',date:new Date().toISOString(),filament:materialRows(quote.value).map(row=>state.value.filaments.find(f=>f.id===row.filamentId)?.name||'Unknown').join(', '),printer:printer.value.name,details:clone(quote.value),items:clone(extraItems.value),result:{...clone(calc.value),cost:quoteGrandCost.value,price:quoteGrandTotal.value,profit:quoteGrandTotal.value-quoteGrandCost.value}});saveMenu.value=false;toast('Quote saved — prices locked to this estimate')}
function loadQuote(q){quote.value={...quote.value,...clone(q.details)};extraItems.value=clone(q.items||[]);page.value='calculator';toast('Quote loaded — review current pricing before saving again')}
const editingProduct=ref(null)
function newProduct(){editingProduct.value={id:uid(),name:'',description:'',customer:'',sku:'',status:'Active',filamentId:quote.value.filamentId||'',printerId:quote.value.printerId||'',grams:num(quote.value.grams),filamentUses:clone(quote.value.filamentUses||null),hours:num(quote.value.hours),minutes:num(quote.value.minutes),price:Number(calc.value.price.toFixed(2)),notes:'',variants:[]}}
function productFromQuote(q){const d=q.details||{};editingProduct.value={id:uid(),name:q.name||'',description:'',customer:'',sku:'',status:'Active',filamentId:d.filamentId||'',filamentUses:clone(d.filamentUses||null),printerId:d.printerId||'',filamentUses:clone(d.filamentUses||null),grams:num(d.grams),hours:num(d.hours),minutes:num(d.minutes),price:Number(q.result?.price||0),notes:'',variants:[]};page.value=enabled('products')?'products':'calculator'}
function saveProduct(){const item=editingProduct.value;if(!item.name.trim()){toast('Enter a product name');return}item.grams=num(item.grams);item.hours=num(item.hours);item.minutes=num(item.minutes);item.price=num(item.price);for(const v of item.variants||[]){v.price=num(v.price);v.grams=num(v.grams);v.filamentUses=(v.filamentUses||[]).map(row=>({filamentId:row.filamentId,grams:num(row.grams)}));v.materials=(v.materials||[]).map(m=>({...m,quantity:num(m.quantity),unitCost:num(m.unitCost)}))}const i=state.value.products.findIndex(p=>p.id===item.id);if(i<0)state.value.products.unshift(clone(item));else state.value.products[i]=clone(item);editingProduct.value=null;toast('Product saved')}
function removeProduct(id){if(!confirm('Delete this saved product?'))return;state.value.products=state.value.products.filter(p=>p.id!==id)}
function loadProduct(p){const v=variantList(p)[0];quote.value={...quote.value,name:p.name,filamentId:v.filamentId,filamentUses:clone(v.filamentUses||null),printerId:v.printerId,grams:v.grams,hours:v.hours,minutes:v.minutes,quantity:1};extraItems.value=[];page.value='calculator';toast('Product loaded — live production costs applied')}
function removeQuote(id){state.value.quotes=state.value.quotes.filter(q=>q.id!==id)}
function exportData(){const blob=new Blob([JSON.stringify(state.value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='printquote-backup.json';a.click();URL.revokeObjectURL(url);toast('Backup downloaded')}
const fileInput=ref(null)
async function importData(e){const f=e.target.files?.[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!Array.isArray(data.filaments)||!Array.isArray(data.printers)||!data.settings)throw Error('Invalid backup');if(!confirm('Replace your current data with this backup?'))return;state.value={...clone(initial),...data,sales:Array.isArray(data.sales)?data.sales:[],products:Array.isArray(data.products)?data.products:[],spools:Array.isArray(data.spools)?data.spools:[],inventoryMovements:Array.isArray(data.inventoryMovements)?data.inventoryMovements:[],printRuns:Array.isArray(data.printRuns)?data.printRuns:[]};quote.value.filamentId=state.value.filaments[0]?.id||'';quote.value.printerId=state.value.printers[0]?.id||'';toast('Backup restored')}catch{toast('Could not read backup file')}finally{e.target.value=''}}
const navItems=[{id:'dashboard',label:'Dashboard',icon:BarChart3},{id:'calculator',label:'Cost calculator',icon:Calculator},{id:'history',label:'Saved quotes',icon:LayoutDashboard},{id:'products',label:'Products',icon:Package},{id:'printHistory',label:'Print history',icon:Clock3},{id:'filaments',label:'Filament library',icon:Layers3},{id:'inventory',label:'Spool inventory',icon:Layers3},{id:'printers',label:'Printer profiles',icon:Printer}]
const features=computed(()=>({...initial.settings.features,...state.value.settings.features}))
const enabled=id=>id==='calculator'||(id==='settings'?authUser.value?.role==='admin':(id==='history'?features.value.quotes:features.value[id]!==false))
const nav=computed(()=>navItems.filter(n=>enabled(n.id)))
const presets={simple:{dashboard:false,quotes:false,products:false,filaments:true,printers:true,sales:false,inventory:false,printHistory:false,advancedCosting:false,forecasting:false},pricing:{dashboard:false,quotes:true,products:true,filaments:true,printers:true,sales:false,inventory:false,printHistory:false,advancedCosting:true,forecasting:false},full:{dashboard:true,quotes:true,products:true,filaments:true,printers:true,sales:true,inventory:true,printHistory:true,advancedCosting:true,forecasting:true}}
function applyPreset(key){state.value.settings.features={...presets[key]};toast('Workspace preset applied')}
function toggleFeature(key){state.value.settings.features={...features.value,[key]:!features.value[key]}}
watch(features,()=>{if(!enabled(page.value)&&page.value!=='administration'&&page.value!=='account')page.value='calculator';if(!features.value.sales)saleProduct.value=null;if(!features.value.printHistory)printingProduct.value=null;if(!features.value.quotes)saveMenu.value=false},{deep:true})
function navigate(id){if(!enabled(id))return;if(id==='administration'){loadUsers();loadActivity();loadReleases()}page.value=id;mobileMenu.value=false;}
const canEdit=computed(()=>authUser.value?.role==='admin'||authUser.value?.role==='user'||authUser.value?.role==='manager')
const pageTitle=computed(()=>page.value==='settings'?'Settings':page.value==='administration'?'Administration':nav.value.find(n=>n.id===page.value)?.label||'Calculator')
watch(authUser,()=>{if(page.value==='settings'&&authUser.value?.role!=='admin')page.value='calculator'})

// Shared first-run guide: completion is persisted in the server-side SQLite state.
const tourActive=ref(false),tourStep=ref(0)
const tourPosition=ref({top:'90px',left:'300px'})
let tourObserver=null
function positionTour(){
  if(!tourActive.value)return
  const target=document.querySelector(`[data-tour="${tourCurrent.value.target}"]`)
  if(!target)return
  const r=target.getBoundingClientRect(), width=Math.min(390,window.innerWidth-24), height=285, gap=18
  let left=r.right+gap
  if(left+width>window.innerWidth-12)left=r.left-width-gap
  if(left<12)left=Math.max(12,Math.min(window.innerWidth-width-12,r.left))
  let top=r.top
  if(top+height>window.innerHeight-12)top=Math.max(12,window.innerHeight-height-12)
  tourPosition.value={top:`${Math.round(top)}px`,left:`${Math.round(left)}px`}
}
watch([tourActive,tourStep,page,mobileMenu],async()=>{await nextTick();positionTour()},{flush:'post'})

// Onboarding is per signed-in user and respects workspace modules and access level.
// Keep completion outside the shared workspace state so one user cannot finish another's tour.
const tourStorageKey=computed(()=>`pq_onboarding_v2_${authUser.value?.id ?? authUser.value?.username ?? 'guest'}`)
function hasCompletedTour(){try{return localStorage.getItem(tourStorageKey.value)==='done'}catch{return true}}
function rememberTourCompletion(){try{localStorage.setItem(tourStorageKey.value,'done')}catch{}}
const tourSteps=computed(()=>{
  // Build the guide from the actual sidebar order, so it never jumps backwards.
  const byPage={
    dashboard:[{title:'Dashboard and analytics',body:'Review your workspace overview, sales trends and the analytics modules enabled for this installation.',target:'tour-dashboard'}],
    calculator:[{title:'Calculate print costs',body:'Estimate material, machine, electricity and labour costs. Save calculations and revisit them through History, even in Calculator-only mode.',target:'tour-calculator'}],
    history:[{title:'Saved quotes',body:canEdit.value?'Save pricing snapshots to preserve customer estimates when material prices change.':'Review saved quote pricing snapshots.',target:'tour-history'}],
    products:[{title:'Products and variants',body:canEdit.value?'Save reusable products and variants, with live costs and separate selling prices.':'Browse saved products and variants.',target:'tour-products'}],
    filaments:[{title:'Your filament library',body:'Browse material profiles, pricing and suppliers.',target:'tour-filaments'},...(canEdit.value?[{title:'Add a filament',body:'Add a material and its price per kilogram for more accurate estimates.',target:'tour-add-filament'}]:[])],
    printHistory:[{title:'Print history & cost accuracy',body:'Record completed and failed print runs, compare estimated and actual costs, and track real material consumption.',target:'tour-printHistory'}],
    inventory:[{title:'Spool inventory',body:canEdit.value?'Track physical spools and record consumption or adjustments.':'Review physical spool stock and inventory history.',target:'tour-inventory'}],
    printers:[{title:'Printer profiles',body:'View printer power consumption, setup time and overhead used in estimates.',target:'tour-printers'},...(canEdit.value?[{title:'Configure a printer',body:'Add printer profiles for more accurate costing.',target:'tour-add-printer'}]:[])]
  }
  const steps=[{title:'Welcome to PrintQuote',body:`Hello ${authUser.value?.firstName||'there'}! We’ll walk through the pages in the same order as your sidebar.`,target:'tour-'+(nav.value[0]?.id||'calculator'),destination:nav.value[0]?.id||'calculator'}]
  for(const item of nav.value)for(const step of byPage[item.id]||[])steps.push({...step,destination:item.id})
  if(authUser.value?.role==='admin'){
    steps.push({title:'Workspace settings',body:'Control costing defaults, appearance and which workspace modules are enabled.',target:'tour-settings',destination:'settings'})
    steps.push({title:'Administration',body:'Manage accounts, permissions, version reminders and scheduled updates from your account menu.',target:'tour-account',destination:'administration'})
  }
  steps.push({title:'You are ready',body:'Your tour is complete. Return to the calculator whenever you want to price a print.',target:'tour-'+(nav.value.at(-1)?.id||'calculator'),destination:nav.value.at(-1)?.id||'calculator'})
  return steps
})
const tourCurrent=computed(()=>tourSteps.value[Math.min(tourStep.value,tourSteps.value.length-1)]||tourSteps.value[0])
function goToTourStep(){const destination=tourCurrent.value?.destination||'calculator';page.value=enabled(destination)||destination==='administration'&&authUser.value?.role==='admin'?destination:'calculator';editingFilament.value=null;editingPrinter.value=null;mobileMenu.value=false;sidebarCollapsed.value=false;accountMenu.value=false}
function startTour(){if(!authUser.value||!ready.value)return;tourStep.value=0;tourActive.value=true;goToTourStep()}
function nextTour(){if(tourStep.value>=tourSteps.value.length-1){finishTour();return}tourStep.value++;goToTourStep()}
function finishTour(){tourActive.value=false;rememberTourCompletion();page.value='calculator';toast('You’re all set! Happy printing ✨')}
function skipTour(){finishTour()}
watch(tourSteps,()=>{if(tourActive.value){tourStep.value=Math.min(tourStep.value,tourSteps.value.length-1);goToTourStep()}},{flush:'post'})

onMounted(()=>{document.addEventListener('pointerdown',onSaveMenuPointerDown);document.addEventListener('keydown',onSaveMenuKeyDown)})
onUnmounted(()=>{document.removeEventListener('pointerdown',onSaveMenuPointerDown);document.removeEventListener('keydown',onSaveMenuKeyDown)})
</script>

<template>
<div v-if="!authReady" class="auth-screen"><div class="auth-card"><h1>PrintQuote</h1><p>Checking your session…</p></div></div>
<div v-else-if="!authUser" class="auth-screen"><form class="auth-card" @submit.prevent="login"><div class="auth-logo"><Box :size="28"/></div><h1>Welcome to PrintQuote</h1><p>Sign in to your workspace</p><label>Username<input v-model.trim="loginDraft.username" required autocomplete="username" autofocus/></label><label>Password<input v-model="loginDraft.password" type="password" required autocomplete="current-password"/></label><label class="remember"><input v-model="loginDraft.remember" type="checkbox"/> Remember me on this device</label><p v-if="loginError" class="auth-error" role="alert">{{loginError}}</p><button class="btn primary" type="submit" :disabled="loginBusy">{{loginBusy?'Signing in…':'Sign in'}}</button></form></div>
<div v-else class="shell" :class="{'dark-mode':isDark,'sidebar-collapsed':sidebarCollapsed,'tour-running':tourActive}" :data-tour-step="tourActive?tourCurrent.target:null" :style="theme">
  <aside class="sidebar" :class="{open:mobileMenu}">
    <div class="brand"><div class="brand-icon"><img v-if="state.settings.logo" :src="state.settings.logo" alt="Site logo"/><Box v-else :size="23" :stroke-width="2.5"/></div><div><strong>{{state.settings.siteTitle||'PrintQuote'}}<span>.</span></strong><small>{{state.settings.siteSubtitle||'PRINT COST STUDIO'}}</small></div></div>
    <button class="sidebar-collapse" type="button" @click="sidebarCollapsed=!sidebarCollapsed" :title="sidebarCollapsed?'Expand sidebar':'Collapse sidebar'" :aria-label="sidebarCollapsed?'Expand sidebar':'Collapse sidebar'"><ChevronRight v-if="sidebarCollapsed" :size="17"/><ChevronLeft v-else :size="17"/></button>
    <nav><button v-for="n in nav" :key="n.id" :title="n.label" :data-tour="'tour-'+n.id" :class="['nav-link',{active:page===n.id}]" @click="navigate(n.id)"><component :is="n.icon" :size="18"/><span>{{n.label}}</span><ChevronRight class="chev" :size="15"/></button></nav>
    <div class="sidebar-footer"><button v-if="authUser?.role==='admin'" class="sidebar-settings" data-tour="tour-settings" :class="{active:page==='settings'}" type="button" @click="navigate('settings')" title="Settings"><Settings2 :size="18"/><span>Settings</span></button></div>
  </aside>
  <div v-if="mobileMenu" class="mobile-overlay" @click="mobileMenu=false"></div>
  <main class="main">
    <header class="topbar"><button class="mobile-toggle" type="button" @click="mobileMenu=!mobileMenu" aria-label="Open navigation"><Menu :size="21"/></button><div class="breadcrumb">Workspace <ChevronRight :size="14"/> <b>{{pageTitle}}</b></div><div class="top-right"><button class="tour-replay" type="button" @click="startTour" title="Show the guided tour" aria-label="Show guided tour"><HelpCircle :size="18"/></button><button class="theme-toggle" type="button" @click="cycleTheme" :title="themeLabel" :aria-label="themeLabel"><Monitor v-if="state.settings.themeMode==='auto'" :size="17"/><Sun v-else-if="state.settings.themeMode==='light'" :size="17"/><Moon v-else :size="17"/><span>{{state.settings.themeMode}}</span></button><div class="account-wrap"><button class="avatar account-trigger" data-tour="tour-account" type="button" @click="accountMenu=!accountMenu" :aria-expanded="accountMenu" aria-label="Account menu">{{initials}}</button><div v-if="accountMenu" class="account-dropdown"><strong>{{authUser.firstName}} {{authUser.lastName}}</strong><small>@{{authUser.username}} · {{authUser.role}}</small><button v-if="authUser.role==='admin'" type="button" @click="page='administration';loadUsers();loadReleases();accountMenu=false"><Users :size="16"/> Administration</button><button type="button" @click="page='account';accountMenu=false"><UserRound :size="16"/> My account</button><button type="button" @click="logout"><LogOut :size="16"/> Sign out</button></div></div></div></header>
    <div v-if="updatedPopup && authUser" class="release-overlay"><div class="release-modal" role="dialog" aria-modal="true" aria-label="Software updated"><h2>PrintQuote has been updated</h2><p>PrintQuote is now running v{{updatedVersion}}.</p><p>Your workspace data remains available. Refresh the page to load the newest interface.</p><button class="btn primary" type="button" @click="reloadApplication()">Refresh now</button><button class="btn" type="button" @click="updatedPopup=false">Later</button></div></div>
    <div v-if="updatePopup && authUser?.role==='admin'" class="release-overlay"><div class="release-modal" role="dialog" aria-modal="true" aria-label="Update available"><h2>PrintQuote update available</h2><p>v{{releaseData.latest}} is available. You're running v{{releaseData.current}}.</p><p>Review the release notes or schedule an upgrade in Administration.</p><button class="btn primary" @click="page='administration';loadUsers();loadReleases();updatePopup=false">View versions</button><button class="btn" @click="dismissRelease">Dismiss this version</button></div></div>
    <div class="content"><div v-if="authUser.role==='viewer'" class="info-box">Read-only account · changes are restricted to managers and administrators.</div><div v-if="authUser.mustChangePassword" class="db-warning">You're using the initial admin password. Please change it under My account before publishing this site.</div>
<div v-if="page==='account'"><div class="page-head"><div><h1>My account</h1><p>{{authUser.firstName}} {{authUser.lastName}} · @{{authUser.username}}</p></div></div><section class="card auth-management"><h2>Change password</h2><p>Use at least 6 characters, one number and one special character.</p><form @submit.prevent="changePassword"><label>Current password<input type="password" v-model="passwordDraft.currentPassword" required autocomplete="current-password"/></label><label>New password<input type="password" v-model="passwordDraft.newPassword" minlength="6" required autocomplete="new-password"/></label><p v-if="passwordError" class="auth-error">{{passwordError}}</p><button class="btn primary" type="submit">Change password</button></form></section></div>
<div v-if="page==='administration' && authUser.role==='admin'"><div class="page-head"><div><h1>Administration</h1><p>Manage who can access this PrintQuote workspace.</p></div></div><section class="card auth-management"><h2>Add user</h2><p>Passwords require 6+ characters, at least one number and one special character.</p><form @submit.prevent="createUser"><label>Username<input v-model.trim="adminDraft.username" required minlength="3" autocomplete="off"/></label><label>Email<input v-model.trim="adminDraft.email" type="email" required/></label><label>First name<input v-model.trim="adminDraft.firstName" required/></label><label>Last name<input v-model.trim="adminDraft.lastName" required/></label><label>Role<select v-model="adminDraft.role"><option value="user">User</option><option value="viewer">Viewer (read-only)</option><option value="admin">Administrator</option></select></label><label>Initial password<input type="password" v-model="adminDraft.password" required minlength="6" autocomplete="new-password"/></label><p v-if="adminError" class="auth-error">{{adminError}}</p><button type="submit" class="btn primary"><Plus :size="16"/> Add user</button></form></section><section class="card auth-management"><h2>Users</h2><div v-for="u in adminUsers" :key="u.id" class="auth-user-row"><span><strong>{{u.firstName}} {{u.lastName}}</strong><small>@{{u.username}} · {{u.role}} · {{u.email||'No email'}}</small></span><button class="btn small" type="button" @click="beginUserEdit(u)">Edit</button><button class="btn small" type="button" @click="resetUserPassword(u)">Reset password by email</button><button v-if="u.id!==authUser.id" class="btn small" @click="deleteUser(u)">Remove</button></div></section></div>
<section v-if="page==='administration' && authUser.role==='admin' && editingUser" class="card auth-management"><h2>Edit user account</h2><p>Changes are emailed to the user. Password resets are emailed directly and never displayed to administrators.</p><form @submit.prevent="saveUserEdit"><label>Username<input v-model.trim="editingUser.username" required minlength="3"/></label><label>First name<input v-model.trim="editingUser.firstName" required/></label><label>Last name<input v-model.trim="editingUser.lastName" required/></label><label>Email<input v-model.trim="editingUser.email" type="email" required/></label><label>Role<select v-model="editingUser.role"><option value="user">User</option><option value="viewer">Viewer (read-only)</option><option value="admin">Administrator</option></select></label><button class="btn primary" type="submit" :disabled="userEditBusy">{{userEditBusy?'Saving…':'Save and notify user'}}</button><button class="btn" type="button" @click="editingUser=null">Cancel</button></form></section><section v-if="page==='administration' && authUser.role==='admin'" class="card v2-panel"><h2>Versions &amp; updates</h2><p class="muted">Running v{{releaseData.current}}. Only releases installed by the server operator appear here. Switching versions requires the host update runner.</p><p v-if="releaseError" class="auth-error">{{releaseError}}</p><div class="update-prefs"><h3>Update preferences</h3><p class="muted">Only locally installed, newer releases are considered. Choose which version component must increase for a reminder or automatic upgrade.</p><label>Update level<select v-model="releaseData.reminderLevel"><option value="major">Major — 1.x.x → 2.x.x</option><option value="minor">Minor — 1.0.x → 1.1.x</option><option value="patch">Patch — 1.0.0 → 1.0.1</option></select></label><label class="update-check"><input type="checkbox" v-model="releaseData.autoUpdate"/> Automatically deploy eligible updates (off by default)</label><p class="muted">Auto-update requires the host update runner. Database backups are made before deployment. Downgrades remain manual.</p><button class="btn primary" type="button" :disabled="updateSettingsBusy" @click="saveUpdatePreferences">{{updateSettingsBusy?'Saving…':'Save update preferences'}}</button></div><button class="btn small" type="button" @click="loadReleases">Check for updates</button><div v-for="r in releaseData.releases" :key="r.version" class="version-entry"><details><summary>v{{r.version}} <span v-if="r.version===releaseData.current">(current)</span> — Read README</summary><pre class="release-readme">{{r.readme}}</pre></details></div><div v-if="!releaseData.releases.length" class="muted">No locally installed release packages found. See README for how to register versions.</div><div v-if="releaseData.releases.length"><h3>Schedule upgrade or downgrade</h3><label>Version<select v-model="releaseTarget"><option v-for="r in releaseData.releases" :key="r.version" :value="r.version">v{{r.version}}</option></select></label><label>Local date and time<input v-model="releaseWhen" type="datetime-local"/></label><button class="btn primary" type="button" @click="scheduleRelease">Schedule deployment</button></div><h3>Scheduled deployments</h3><div v-for="job in releaseData.schedules" :key="job.id" class="stock-row"><span>v{{job.version}} · {{new Date(job.execute_at).toLocaleString()}} · {{job.status}}<small v-if="job.error">{{job.error}}</small></span><button v-if="job.status==='pending'" class="btn small" type="button" @click="cancelRelease(job.id)">Cancel</button></div></section>
<section v-if="page==='administration' && authUser.role==='admin'" class="card v2-panel"><h2>Collaboration & activity</h2><p class="muted">Admins manage accounts and releases; users can edit products, sales and stock. Viewers can browse the workspace and use the calculator without saving changes. Users can edit; administrators also manage accounts and settings.</p><div v-for="u in adminUsers" :key="'role-'+u.id" class="stock-row"><span>{{u.firstName}} {{u.lastName}} (@{{u.username}})</span><button class="btn small" type="button" @click="beginUserEdit(u)">Edit account</button></div><button class="btn small" @click="loadActivity">Refresh activity</button><p v-if="activityError">{{activityError}}</p><div v-for="event in activityLog.slice(0,25)" :key="event.id" class="stock-row"><span>{{event.actor}} · {{event.action}}</span><small>{{new Date(event.created_at).toLocaleString()}}</small></div><p v-if="!activityLog.length" class="muted">No activity recorded yet.</p></section>
<div v-if="!ready" class="db-warning">Cannot load the shared workspace. Check the application API container and refresh the page. No local changes will be saved until the connection succeeds.</div>
      <div v-if="page==='dashboard' && features.dashboard" class="dashboard-page">
 <div class="page-head"><div><div class="eyebrow">YOUR WORKSPACE</div><h1>Dashboard</h1><p>Your printing costs, best sellers and recent sales at a glance.</p></div><div v-if="features.sales" class="field"><label>Sales period</label><select v-model="dateWindow"><option value="7">Last 7 days</option><option value="30">Last 30 days</option><option value="90">Last 90 days</option><option value="365">Last year</option><option value="all">All time</option></select></div><button class="btn primary" @click="navigate('calculator')"><Calculator :size="17"/> New estimate</button></div>
 <div v-if="!features.sales" class="stats-grid"><div class="stat"><div class="stat-top">Saved products <Package :size="19"/></div><div class="stat-value">{{state.products.length}}</div><small>Your reusable designs</small></div><div class="stat"><div class="stat-top">Saved quotes <LayoutDashboard :size="19"/></div><div class="stat-value">{{state.quotes.length}}</div><small>Stored estimates</small></div><div class="stat"><div class="stat-top">Materials <Layers3 :size="19"/></div><div class="stat-value">{{state.filaments.length}}</div><small>Filament profiles</small></div></div><div v-if="features.sales" class="stats-grid"><div class="stat"><div class="stat-top">Sales revenue <ShoppingBag :size="19"/></div><div class="stat-value">{{money(filteredSummary.revenue)}}</div><small>Recorded sales</small></div><div class="stat"><div class="stat-top">Estimated gross profit <TrendingUp :size="19"/></div><div class="stat-value profit">{{money(filteredSummary.profit)}}</div><small>Based on costs when each sale was logged</small></div><div class="stat"><div class="stat-top">Items sold <Package :size="19"/></div><div class="stat-value">{{filteredSummary.units}}</div><small>{{state.products.length}} saved products · {{state.quotes.length}} quotes</small></div></div>
 <div v-if="features.sales" class="dashboard-columns"><section class="card"><div class="card-heading"><div><h2>Revenue over time</h2><p>Last six calendar months · recorded sales only</p></div><BarChart3 :size="20"/></div><div class="sales-chart"><div v-for="month in monthlyTrend" :key="month.key" class="sales-bar-col"><strong>{{money(month.revenue)}}</strong><div class="sales-bar-track"><div class="sales-bar" :style="{height:Math.max(month.revenue?6:0,month.revenue/trendMax*100)+'%'}"></div></div><span>{{month.label}}</span></div></div><div class="info-box"><Info :size="16"/>{{forecast===null?'Add sales across at least two previous months to unlock a basic demand estimate.':'Indicative next-month demand: around '+forecast+' items, based on recent recorded months. Not a guarantee or market-wide forecast.'}}</div></section>
 <section class="card"><div class="card-heading"><div><h2>Most popular products</h2><p>Ranked by units sold</p></div><Package :size="20"/></div><div v-if="!ranking.length" class="empty">Save a product to see it here.</div><div v-for="(p,i) in ranking.slice(0,6)" :key="p.id" class="ranking-row"><span class="ranking-index">{{i+1}}</span><div><strong>{{p.name}}</strong><small>{{p.units}} sold · {{money(p.revenue)}} revenue</small></div><button v-if="canEdit && (features.sales)" class="btn small" @click="beginSale(p)">+ Sale</button></div></section></div>
 <section v-if="features.sales" class="card v2-panel"><div class="card-heading"><div><h2>Profitability & sales insights</h2><p>Based on recorded sales in your selected date range, using saved cost snapshots.</p></div></div><div class="v2-metrics"><div><small>Gross margin</small><strong>{{salesAnalytics.margin.toFixed(1)}}%</strong></div><div><small>Average sale</small><strong>{{money(salesAnalytics.averageOrder)}}</strong></div><div><small>Top product revenue share</small><strong>{{salesAnalytics.topShare.toFixed(1)}}%</strong></div></div><h3>Most profitable products</h3><div v-for="p in salesAnalytics.rows.slice(0,8)" :key="p.name" class="stock-row"><span>{{p.name}} · {{p.units}} units</span><strong>{{money(p.profit)}} profit</strong></div><p v-if="!salesAnalytics.rows.length" class="muted">Record sales to see profitability insights.</p><div v-if="features.forecasting" class="info-box"><Info :size="17"/><span v-if="forecastDetails">Next-month demand estimate: <strong>{{forecastDetails.prediction}} units</strong> (indicative range {{forecastDetails.range[0]}}–{{forecastDetails.range[1]}}). Confidence: {{forecastDetails.confidence}}. Based on {{forecastDetails.months}} months with sales; seasonal trends and external demand are not modelled.</span><span v-else>Forecast unavailable: record sales in at least two separate months.</span></div></section>
<section v-if="features.inventory" class="card inventory-summary"><div class="card-heading"><div><h2>Filament stock</h2><p>Physical spools and remaining material</p></div><button class="btn small" @click="navigate('inventory')">Manage spools</button></div><div v-for="sp in inventorySpools.slice(0,8)" :key="sp.id" class="stock-row"><strong>{{sp.label}}</strong><span :class="{'stock-low':num(sp.remainingGrams)<=150}">{{num(sp.remainingGrams)}}g remaining</span></div><p v-if="!inventorySpools.length" class="muted">Add physical spools to begin inventory tracking.</p></section><section v-if="features.sales" class="card recent-sales"><div class="card-heading"><div><h2>Recent sales</h2><p>Actual recorded sales, not quotes</p></div></div><div class="table-wrap"><table><thead><tr><th>DATE</th><th>PRODUCT</th><th>QTY</th><th>REVENUE</th><th></th></tr></thead><tbody><tr v-for="sale in recentSales" :key="sale.id"><td>{{sale.date}}</td><td>{{sale.productName}}</td><td>{{sale.quantity}}</td><td class="bold">{{money(sale.quantity*sale.unitPrice)}}</td><td><button v-if="canEdit" class="icon-button danger" title="Delete sale" @click="removeSale(sale.id)"><Trash2 :size="15"/></button></td></tr><tr v-if="!recentSales.length"><td colspan="5" class="empty">No sales recorded yet. Open Products and select Record sale to begin.</td></tr></tbody></table></div></section>
 </div>
 <div v-if="page==='calculator'">
        <div class="page-head"><div><div class="eyebrow">PRINT COSTING</div><h1>Print cost calculator</h1><p>Know your costs. Price every print with confidence. <span v-if="!canEdit">Read-only access: estimates are temporary and cannot be saved.</span></p></div><div class="save-actions"><div v-if="canEdit" ref="saveDropdownRef" class="save-dropdown unified-save"><button class="btn primary unified-save-trigger" type="button" aria-haspopup="menu" :aria-expanded="saveMenu" @click="saveMenu=!saveMenu"><Plus :size="17"/><span>{{defaultSaveLabel}}</span><ChevronDown :size="18" class="unified-save-chevron" :class="{rotated:saveMenu}"/></button><div v-if="saveMenu" class="save-dropdown-menu" role="menu" aria-label="Save options"><button v-if="features.quotes" role="menuitem" type="button" @click="saveQuote();closeSaveMenu()"><Plus :size="16"/> Save quote <Check v-if="features.quotes" :size="15" class="save-default-check"/></button><button role="menuitem" type="button" @click="saveCalculation();closeSaveMenu()"><Clock3 :size="16"/> Save calculation <Check v-if="!features.quotes" :size="15" class="save-default-check"/></button><button v-if="features.products" role="menuitem" type="button" @click="productFromCalculator();closeSaveMenu()"><Package :size="16"/> Save as product</button></div></div><button class="btn" @click="showCalculationHistory=!showCalculationHistory"><Clock3 :size="17"/> History ({{state.calculations.length}})</button></div></div>
        <section v-if="showCalculationHistory" class="card calculation-history"><div class="card-heading"><div><h2>Calculation history</h2><p>Saved estimates remain available even when Quotes and Products are disabled. Prices shown are snapshots from when each calculation was saved.</p></div><button class="icon-button" title="Close history" @click="showCalculationHistory=false"><X :size="18"/></button></div><div class="field"><label>Search history</label><input v-model="historySearch" placeholder="Search by project, printer or filament"/></div><div class="table-wrap"><table><thead><tr><th>DATE</th><th>PROJECT</th><th>MATERIAL / PRINTER</th><th>PRODUCTION COST</th><th>SELLING PRICE</th><th>ACTIONS</th></tr></thead><tbody><tr v-for="h in filteredCalculationHistory" :key="h.id"><td>{{new Date(h.date).toLocaleString()}}</td><td><strong>{{h.name}}</strong></td><td>{{h.filament}} · {{h.printer}}</td><td>{{money(h.result.cost)}}</td><td><strong>{{money(h.result.price)}}</strong></td><td class="actions"><button class="btn small" @click="loadCalculation(h)">Load</button><button v-if="canEdit" class="icon-button danger" title="Delete calculation" @click="removeCalculation(h.id)"><Trash2 :size="16"/></button></td></tr><tr v-if="!filteredCalculationHistory.length"><td colspan="6" class="empty">No matching saved calculations. Save an estimate to build your history.</td></tr></tbody></table></div></section>
        <div class="stats-grid">
          <div class="stat"><div class="stat-top"><span>Total production cost</span><div class="mini-icon violet"><PoundSterling :size="17"/></div></div><div class="stat-value">{{money(calc.cost)}}</div><small>All costs included</small></div>
          <div class="stat"><div class="stat-top"><span>Suggested selling price</span><div class="mini-icon blue"><Calculator :size="17"/></div></div><div class="stat-value">{{money(calc.price)}}</div><small>{{calc.margin}}% profit margin</small></div>
          <div class="stat"><div class="stat-top"><span>Estimated profit</span><div class="mini-icon green"><TrendingUp :size="17"/></div></div><div class="stat-value profit">{{money(calc.profit)}}</div><small>{{money(calc.unit)}} per item selling price</small></div>
        </div>
        <div v-if="features.quotes && features.products" class="card quote-products"><div class="card-heading"><div><h2>Products in this quote</h2><p>Add saved products as extra line items. Their selling prices are captured when you save.</p></div></div><div class="quote-picker"><select aria-label="Choose saved product" id="quote-product-select"><option value="">Select a saved product…</option><option v-for="p in state.products" :key="p.id" :value="p.id">{{p.name}} — {{money(p.price)}}</option></select><button v-if="canEdit" class="btn" @click="addSelectedProduct">Add to quote</button></div><div v-for="item in extraItems" :key="item.id" class="quote-line"><strong>{{item.name}}</strong><label>Quantity <input type="number" min="1" step="1" v-model.number="item.quantity"/></label><span>{{money(item.unitPrice)}} each</span><button v-if="canEdit" class="icon-button danger" @click="removeQuoteItem(item.id)" title="Remove line"><Trash2 :size="16"/></button></div><div v-if="extraItems.length" class="quote-line-total"><strong>Quote total (calculator + saved products)</strong><strong>{{money(quoteGrandTotal)}}</strong></div></div>
        <div class="two-col">
          <section class="card"><div class="card-heading"><div><h2>Print details</h2><p>Enter your slicer estimates and select materials.</p></div><div class="card-badge">01 / INPUT</div></div>
            <div class="field"><label>Project name <span>Optional</span></label><input v-model="quote.name" placeholder="e.g. Custom phone stand"/></div>
            <div class="field"><label>Printer</label><select v-model="quote.printerId"><option disabled value="">Select printer</option><option v-for="p in state.printers" :value="p.id" :key="p.id">{{p.name}}</option></select></div>
            <div class="field"><label>Filament materials <span>grams per item</span></label><div v-for="(row,i) in (quote.filamentUses?.length?quote.filamentUses:[{filamentId:quote.filamentId,grams:quote.grams}])" :key="i" class="field-grid material-line"><select :value="row.filamentId" @change="quote.filamentUses?.length ? (row.filamentId=$event.target.value) : (quote.filamentId=$event.target.value)"><option disabled value="">Select filament</option><option v-for="f in state.filaments" :value="f.id" :key="f.id">{{f.brand ? f.brand+' · ' : ''}}{{f.name}}</option></select><div class="input-unit"><input type="number" min="0" step="0.1" :value="row.grams" @input="quote.filamentUses?.length ? (row.grams=Number($event.target.value)) : (quote.grams=Number($event.target.value))"/><span>g</span></div><button v-if="quote.filamentUses?.length" type="button" class="icon-button danger" title="Remove material" @click="removeQuoteFilament(i)"><X :size="16"/></button></div><button type="button" class="btn small" @click="addQuoteFilament"><Plus :size="15"/> Add another filament</button></div>
            <div class="field"><label>Quantity</label><div class="input-unit"><input type="number" min="1" step="1" v-model.number="quote.quantity"/><span>pcs</span></div></div>
            <div class="field"><label>Print duration <span>per item</span></label><div class="field-grid"><div class="input-unit"><input type="number" min="0" step="1" v-model.number="quote.hours"/><span>hours</span></div><div class="input-unit"><input type="number" min="0" max="59" step="1" v-model.number="quote.minutes"/><span>min</span></div></div></div>
            <div class="field-grid"><div class="field"><label>Target profit margin</label><div class="input-unit"><input type="number" min="0" max="99.9" step="1" v-model.number="quote.margin"/><span>%</span></div></div><div class="field"><label>Extra cost <span>per item</span></label><div class="input-unit"><input type="number" min="0" step="0.01" v-model.number="quote.extraCost"/><span>{{state.settings.currency==='GBP'?'£':state.settings.currency==='USD'?'$':'€'}}</span></div></div></div>
            <div class="info-box"><Info :size="17"/><span>Printer setup, post-processing, power consumption and machine overhead are pulled automatically from your printer profile.</span></div>
          </section>
          <section class="card result-card"><div class="card-heading"><div><h2>Cost breakdown</h2><p>A clear view of where every penny goes.</p></div><div class="card-badge">02 / RESULTS</div></div>
            <div class="breakdown"><div class="cost-row"><div><span class="cost-icon"><Layers3 :size="16"/></span>Filament <small>{{num(quote.grams)*calc.qty}}g total</small></div><strong>{{money(calc.material)}}</strong></div><div class="cost-row"><div><span class="cost-icon"><Zap :size="16"/></span>Electricity <small>{{printer?.power||0}} W</small></div><strong>{{money(calc.energy)}}</strong></div><div class="cost-row"><div><span class="cost-icon"><Clock3 :size="16"/></span>Labour <small>Setup + finishing</small></div><strong>{{money(calc.labour)}}</strong></div><div class="cost-row"><div><span class="cost-icon"><Printer :size="16"/></span>Machine overhead <small>Wear & maintenance</small></div><strong>{{money(calc.overhead)}}</strong></div><div class="cost-row"><div><span class="cost-icon"><Plus :size="16"/></span>Additional costs</div><strong>{{money(calc.extras)}}</strong></div></div>
            <div class="totals"><div><span>Production cost</span><strong>{{money(calc.cost)}}</strong></div><div><span>Profit ({{calc.margin}}% margin)</span><strong class="profit">+ {{money(calc.profit)}}</strong></div></div>
            <div class="grand-total"><div><span>RECOMMENDED SELLING PRICE</span><strong>{{money(calc.price)}}</strong><small>{{money(calc.unit)}} per item · {{calc.qty}} item{{calc.qty===1?'':'s'}}</small></div><TrendingUp :size="29"/></div>
            <p class="footnote">Profit margin = profit ÷ selling price. This differs from markup, which is profit ÷ cost. Prices exclude VAT and payment/platform fees unless added as extra costs.</p>
          </section>
        </div>
      </div>
      <div v-if="page==='filaments' && features.filaments"><div class="page-head"><div><div class="eyebrow">MATERIALS</div><h1>Filament library</h1><p>Keep your materials, cost per kilogram and supplier links in one place.</p></div><button v-if="canEdit" class="btn primary" data-tour="tour-add-filament" @click="newFilament"><Plus :size="17"/> Add filament</button></div><div class="table-card"><div class="table-wrap"><table><thead><tr><th>FILAMENT</th><th>MATERIAL</th><th>COLOUR</th><th>PRICE / KG</th><th>SUPPLIER</th><th v-if="features.inventory">STOCK</th><th></th></tr></thead><tbody><tr v-for="f in state.filaments" :key="f.id"><td><strong>{{f.name}}</strong><small>{{f.brand||'Unbranded'}}</small></td><td><span class="tag">{{f.material}}</span></td><td>{{f.colour||'—'}}</td><td class="bold">{{money(f.price)}}</td><td><a v-if="f.url" :href="f.url" target="_blank" rel="noopener noreferrer" class="link">Buy filament <ExternalLink :size="13"/></a><span v-else class="muted">Not set</span></td><td v-if="features.inventory"><span :class="{'stock-low':num(f.stockGrams)<=num(f.lowStockGrams)}">{{num(f.stockGrams)}}g <span v-if="num(f.stockGrams)<=num(f.lowStockGrams)">· Low</span></span></td><td class="actions"><button v-if="canEdit" class="btn small" @click="editFilament(f)">Edit</button><button v-if="canEdit" class="icon-button danger" title="Delete" @click="removeFilament(f.id)"><Trash2 :size="16"/></button></td></tr><tr v-if="!state.filaments.length"><td :colspan="features.inventory?7:6" class="empty">No filaments yet. Add your first material to get started.</td></tr></tbody></table></div></div><div class="info-box page-info"><Info :size="17"/><span v-if="features.inventory">Track stock manually in each filament profile. Stock is not automatically deducted when recording sales.</span><span v-else>Enable optional stock tracking in Settings → Workspace features.</span></div></div>
      <div v-if="page==='printers' && features.printers"><div class="page-head"><div><div class="eyebrow">EQUIPMENT</div><h1>Printer profiles</h1><p>Configure a cost profile for every printer model you use.</p></div><button v-if="canEdit" class="btn primary" data-tour="tour-add-printer" @click="newPrinter"><Plus :size="17"/> Add printer</button></div><div class="printer-grid"><div v-for="p in state.printers" :key="p.id" class="card printer-card"><div class="printer-top"><div class="printer-illustration"><Printer :size="27"/></div><span class="tag">{{p.technology}}</span></div><h2>{{p.name}}</h2><div class="printer-details"><div><span>Average power</span><strong>{{p.power}} W</strong></div><div><span>Setup time / job</span><strong>{{p.setupMinutes}} min</strong></div><div><span>Post-processing / item</span><strong>{{p.postMinutes}} min</strong></div><div><span>Machine overhead / hr</span><strong>{{money(p.overheadRate)}}</strong></div></div><div class="printer-actions"><button v-if="canEdit" class="btn small" @click="editPrinter(p)">Edit profile</button><button v-if="canEdit" class="icon-button danger" @click="removePrinter(p.id)"><Trash2 :size="16"/></button></div></div><button v-if="canEdit" class="add-card" @click="newPrinter"><Plus :size="26"/><strong>Add printer profile</strong><span>Set up another machine</span></button></div></div>
      <div v-if="page==='history' && features.quotes"><div class="page-head"><div><div class="eyebrow">YOUR PROJECTS</div><h1>Saved quotes</h1><p>Review past estimates and reuse them for your next print.</p></div></div><div class="table-card"><div class="table-wrap"><table><thead><tr><th>PROJECT</th><th>DATE</th><th>PRINTER</th><th>PRODUCTION COST</th><th>SELLING PRICE</th><th>PROFIT</th><th></th></tr></thead><tbody><tr v-for="q in state.quotes" :key="q.id"><td><strong>{{q.name}}</strong><small>{{q.filament}}</small></td><td>{{new Date(q.date).toLocaleDateString('en-GB')}}</td><td>{{q.printer}}</td><td>{{money(q.result.cost)}}</td><td class="bold">{{money(q.result.price)}}</td><td class="profit bold">{{money(q.result.profit)}}</td><td class="actions"><button class="btn small" @click="loadQuote(q)">Load</button><button v-if="canEdit && (features.products)" class="btn small" @click="productFromQuote(q)">Make product</button><button v-if="canEdit" class="icon-button danger" @click="removeQuote(q.id)"><Trash2 :size="16"/></button></td></tr><tr v-if="!state.quotes.length"><td colspan="7" class="empty">No saved quotes yet. Create an estimate and click “Save quote”.</td></tr></tbody></table></div></div></div>
      <div v-if="page==='printHistory' && features.printHistory"><div class="page-head"><div><div class="eyebrow">PRODUCTION RECORDS</div><h1>Print history</h1><p>Compare estimated costs with real print consumption, including failed prints.</p></div></div><div class="stats-grid"><div class="stat-card"><span>Print runs</span><strong>{{printStats.runs}}</strong></div><div class="stat-card"><span>Failed runs</span><strong>{{printStats.failed}}</strong></div><div class="stat-card"><span>Actual production cost</span><strong>{{money(printStats.actual)}}</strong></div><div class="stat-card"><span>Cost variance</span><strong>{{money(printStats.variance)}}</strong></div></div><section class="card"><div class="card-heading"><div><h2>Actual vs estimated</h2><p>Historical estimates and actuals are fixed when a run is recorded. Negative variance means a lower actual cost.</p></div><div class="field"><label>Show</label><select v-model="printHistoryFilter"><option value="all">All print runs</option><option value="successful">Successful</option><option value="failed">Failed</option></select></div></div><div class="table-wrap"><table><thead><tr><th>DATE</th><th>PRODUCT / PRINTER</th><th>RESULT</th><th>FILAMENT (EST. / ACT.)</th><th>TIME (EST. / ACT.)</th><th>COST (EST. / ACT.)</th><th>DIFFERENCE</th><th></th></tr></thead><tbody><tr v-for="run in printHistoryRows" :key="run.id"><td>{{new Date(run.date).toLocaleString()}}</td><td><strong>{{run.productName}} · {{run.variantName}}</strong><br/><small>{{run.printerName}} · {{run.quantity}} units</small></td><td>{{run.success?'Success':'Failed'}}</td><td>{{run.estimatedGrams.toFixed(1)}}g / {{run.actualGrams.toFixed(1)}}g</td><td>{{run.estimatedHours.toFixed(2)}}h / {{run.actualHours.toFixed(2)}}h</td><td>{{money(run.estimatedCost)}} / {{money(run.actualCost)}}</td><td><strong>{{money(run.actualCost-run.estimatedCost)}}</strong></td><td><button v-if="canEdit" class="icon-button danger" title="Delete print record" @click="removePrintRun(run)"><Trash2 :size="16"/></button></td></tr><tr v-if="!printHistoryRows.length"><td colspan="8" class="empty">No print runs recorded yet. Open Products and select Record print to get started.</td></tr></tbody></table></div></section><section class="card"><h2>Waste & accuracy</h2><p>Failed prints used {{printStats.materialWaste.toFixed(1)}}g of filament. Total estimated production cost: {{money(printStats.estimated)}}; actual production cost: {{money(printStats.actual)}}.</p><p class="hint">This history helps identify systematic underestimates. It does not automatically modify pricing or printer profiles.</p></section></div>
      <div v-if="page==='products' && features.products">
  <div class="page-head"><div><div class="eyebrow">YOUR CATALOGUE</div><h1>Products</h1><p>Keep finished designs and repeat orders separate from one-off quotes.</p></div><button v-if="canEdit" class="btn primary" @click="newProduct"><Plus :size="17"/> Add product</button></div>
  <div class="product-grid"><article v-for="item in state.products" :key="item.id" class="card product-card"><div class="product-top"><div class="product-icon"><Package :size="22"/></div><span class="product-status">{{item.status||'Active'}}</span></div><h2>{{item.name}}</h2><p class="product-description">{{item.description||'No description yet'}}</p><div class="product-meta"><span v-if="item.customer">For {{item.customer}}</span><span v-if="item.sku">{{item.sku}}</span><span>{{state.filaments.find(f=>f.id===item.filamentId)?.name||'Filament not selected'}}</span><span>{{state.printers.find(p=>p.id===item.printerId)?.name||'Printer not selected'}}</span></div><div class="product-price"><small>Selling price</small><strong>{{money(item.price)}}</strong><small v-if="productCost(item)!==null">Live cost {{money(productCost(item))}} · {{productMargin(item)?.toFixed(1)}}% margin</small><small v-else>Assign a valid filament and printer to calculate cost</small></div><div v-if="variantList(item).length>1" class="field"><label>Choose variant for quote</label><select v-model="selectedVariantId"><option v-for="v in variantList(item)" :key="v.id" :value="v.id">{{v.name}} · {{money(v.price)}}</option></select></div><div class="product-popularity">{{productUnits(item)}} units sold · {{variantList(item).length}} variant(s)<span v-if="features.forecasting"> · Next month ~{{productForecast(item).units}} ({{productForecast(item).confidence}})</span></div><div class="product-actions"><button class="btn small" @click="loadProduct(item)">Cost</button><button v-if="canEdit && (features.quotes)" class="btn small" @click="addQuoteProduct(item)">Add to quote</button><button class="btn small" v-if="canEdit && features.printHistory" @click="beginPrint(item)">Record print</button><button class="btn small" v-if="canEdit && features.sales" @click="beginSale(item)">Record sale</button><button v-if="canEdit" class="btn small" @click="editingProduct=clone(item)">Edit</button><button v-if="canEdit" class="icon-button danger" aria-label="Delete product" @click="removeProduct(item.id)"><Trash2 :size="16"/></button></div></article>
  <button v-if="canEdit" class="add-card product-add" @click="newProduct"><Plus :size="28"/><strong>Add your first product</strong><span>Save a reusable design or client job</span></button></div>
</div>
<div v-if="page==='inventory' && features.inventory"><div class="page-head"><div><div class="eyebrow">MATERIAL STOCK</div><h1>Physical spools</h1><p>Track purchased rolls separately from filament pricing profiles.</p></div></div><section class="card"><h2>Add spool</h2><div class="field-grid"><div class="field"><label>Filament</label><select v-model="spoolDraft.filamentId"><option value="">Choose filament</option><option v-for="f in state.filaments" :key="f.id" :value="f.id">{{f.name}}</option></select></div><div class="field"><label>Spool label</label><input v-model="spoolDraft.label" placeholder="e.g. Black PLA #2"/></div><div class="field"><label>Original weight (g)</label><input type="number" min="1" v-model.number="spoolDraft.originalGrams"/></div><div class="field"><label>Remaining weight (g)</label><input type="number" min="0" v-model.number="spoolDraft.remainingGrams"/></div><div class="field"><label>Purchase price</label><input type="number" min="0" step="0.01" v-model.number="spoolDraft.purchasePrice"/></div><div class="field"><label>Storage location</label><input v-model="spoolDraft.location" placeholder="Shelf A"/></div></div><button v-if="canEdit" class="btn primary" @click="addSpool">Add spool</button></section><section class="card"><h2>Current stock</h2><div v-for="sp in inventorySpools" :key="sp.id" class="stock-row"><div><strong>{{sp.label}}</strong><p class="hint">{{state.filaments.find(f=>f.id===sp.filamentId)?.name||'Unknown filament'}} · {{sp.location||'No location'}}</p></div><strong>{{num(sp.remainingGrams)}}g / {{num(sp.originalGrams)}}g</strong><button v-if="canEdit" class="btn small" @click="inventorySpool=sp;inventoryQuantity=0">Adjust</button></div><p v-if="!inventorySpools.length" class="muted">No spools recorded yet.</p></section><section class="card"><h2>Recent stock movements</h2><div v-for="m in state.inventoryMovements.slice(0,12)" :key="m.id" class="stock-row"><span>{{m.date.slice(0,10)}} · {{m.reason}}</span><strong>{{m.delta>0?'+':''}}{{m.delta}}g</strong></div></section></div><div v-if="canEdit && inventorySpool" class="modal-backdrop" @click.self="inventorySpool=null"><form class="modal" @submit.prevent="adjustSpool"><h2>Adjust {{inventorySpool.label}}</h2><div class="field"><label>Change in grams (+ to add, − to use)</label><input required type="number" step="0.1" v-model.number="inventoryQuantity"/></div><div class="field"><label>Reason</label><select v-model="inventoryReason"><option>Adjustment</option><option>Print used</option><option>Failed print</option><option>Waste</option><option>Restock correction</option></select></div><div class="modal-actions"><button type="button" class="btn" @click="inventorySpool=null">Cancel</button><button class="btn primary">Save adjustment</button></div></form></div><div v-if="page==='settings' && authUser?.role==='admin'"><div class="page-head"><div><div class="eyebrow">PREFERENCES</div><h1>Settings</h1><p>Set the rates used across all your cost estimates.</p></div></div><section class="card workspace-panel"><div class="card-heading"><div><h2>Workspace features</h2><p>Choose a simple calculator or enable the tools you actually need. Hidden pages keep their saved data.</p></div><Layers3 :size="21" class="muted"/></div><div class="preset-row"><button type="button" class="btn" @click="applyPreset('simple')">Calculator only</button><button type="button" class="btn" @click="applyPreset('pricing')">Product pricing</button><button type="button" class="btn" @click="applyPreset('full')">Full workspace</button></div><div class="feature-grid"><label v-for="item in [{id:'dashboard',title:'Dashboard',hint:'Overview and statistics'},{id:'quotes',title:'Saved quotes',hint:'Save and reuse estimates'},{id:'products',title:'Products',hint:'Catalogue and live costs'},{id:'filaments',title:'Filament library',hint:'Material pricing profiles'},{id:'printers',title:'Printer profiles',hint:'Power, labour and overhead'},{id:'printHistory',title:'Print history',hint:'Actual costs, failures and waste'},{id:'sales',title:'Sales analytics',hint:'Sales logging and forecasts'},{id:'inventory',title:'Filament stock',hint:'Physical spools and stock movements'},{id:'advancedCosting',title:'Advanced costing',hint:'Variants, packaging and bill of materials'},{id:'forecasting',title:'Demand forecasting',hint:'Weighted sales predictions'}]" :key="item.id" class="feature-option"><div><strong>{{item.title}}</strong><small>{{item.hint}}</small></div><input type="checkbox" :checked="features[item.id]" @change="toggleFeature(item.id)" :aria-label="'Enable '+item.title"/></label></div><div class="info-box"><Info :size="17"/>The calculator is always available. Settings are restricted to administrators. Hiding a page never deletes its records. Filament and printer profiles still power costing when their pages are hidden.</div></section><section class="card branding-panel"><div class="card-heading"><div><h2>Appearance & branding</h2><p>Personalise the entire workspace. Changes appear instantly.</p></div><Settings2 :size="21" class="muted"/></div><div class="branding-grid"><div><div class="field"><label>Site title</label><input v-model="state.settings.siteTitle" maxlength="36" placeholder="PrintQuote"/></div><div class="field"><label>Subtitle / tagline</label><input v-model="state.settings.siteSubtitle" maxlength="50" placeholder="PRINT COST STUDIO"/></div><div class="field"><label>Logo image</label><div class="logo-picker"><div class="logo-preview"><img v-if="state.settings.logo" :src="state.settings.logo" alt="Logo preview"/><Box v-else :size="25"/></div><div><button class="btn small" @click="logoInput?.click()"><Upload :size="15"/> Upload logo</button><button v-if="state.settings.logo" class="btn small" @click="state.settings.logo=''">Remove</button><p class="hint">PNG, JPG, SVG or WebP · max 1 MB</p></div><input ref="logoInput" type="file" accept="image/*" hidden @change="uploadLogo"/></div></div></div><div><div class="field"><label>Accent colour</label><div class="colour-field"><input type="color" v-model="state.settings.accent"/><input v-model="state.settings.accent" aria-label="Accent colour hex" maxlength="7"/></div></div><div class="field"><label>Theme preference</label><select v-model="state.settings.themeMode"><option value="auto">Automatic (system)</option><option value="light">Light</option><option value="dark">Dark</option></select></div><div class="field"><label>Dark canvas colour</label><div class="colour-field"><input type="color" v-model="state.settings.darkBackground"/><input v-model="state.settings.darkBackground" maxlength="7"/></div></div><div class="field"><label>Light canvas colour</label><div class="colour-field"><input type="color" v-model="state.settings.background"/><input v-model="state.settings.background" aria-label="Background colour hex" maxlength="7"/></div></div><p class="appearance-note">A soft, layered canvas keeps your workspace calm and readable in both light and dark mode.</p><button class="btn small" @click="Object.assign(state.settings,{accent:'#5277e8',background:'#f3f7ff',darkBackground:'#1b283d',themeMode:'auto'})">Reset colours</button></div></div></section><div class="settings-layout"><section class="card"><div class="card-heading"><div><h2>Business rates</h2><p>Changes are saved automatically.</p></div><Settings2 :size="21" class="muted"/></div><div class="field"><label>Currency</label><select v-model="state.settings.currency"><option value="GBP">British Pound (£)</option><option value="EUR">Euro (€)</option><option value="USD">US Dollar ($)</option></select></div><div class="field"><label>Electricity price <span>per kWh</span></label><div class="input-unit"><input type="number" min="0" step="0.001" v-model.number="state.settings.energyRate"/><span>/ kWh</span></div></div><div class="field"><label>Labour rate <span>per hour</span></label><div class="input-unit"><input type="number" min="0" step="0.5" v-model.number="state.settings.labourRate"/><span>/ hr</span></div></div><div class="field"><label>Default margin <span>for new estimates</span></label><div class="input-unit"><input type="number" min="0" max="99.9" step="1" v-model.number="state.settings.defaultMargin" @change="quote.margin=state.settings.defaultMargin"/><span>%</span></div></div><div class="info-box"><Info :size="17"/>Electricity is calculated from average printer wattage × print duration × your kWh rate. Labour uses the setup and finishing times saved in each printer profile.</div></section><section class="card"><div class="card-heading"><div><h2>Your data</h2><p>Export or restore the shared workspace.</p></div><Download :size="21" class="muted"/></div><p class="secondary-text">Filaments, printers, branding, rates and saved quotes are stored in the built-in SQLite database and shared by every device accessing this server. You can also export a JSON backup.</p><div class="backup-actions"><button class="btn" @click="exportData"><Download :size="16"/> Export backup</button><button class="btn" @click="fileInput?.click()"><Upload :size="16"/> Import backup</button><input ref="fileInput" type="file" accept="application/json,.json" hidden @change="importData"/></div><div class="info-box"><Info :size="17"/>Browser storage is not used for application data. Back up the SQLite database file regularly. This deployment is intended for a trusted private network; add authentication before publishing it online.</div></section></div></div>
      <footer>PrintQuote <span>•</span> Built for makers, designed for clear pricing.</footer>
    </div>
  </main>
  <div v-if="tourActive && ready" class="tour-layer" aria-live="polite">
    <div class="tour-scrim"></div>
    <div class="tour-panel" :style="tourPosition" role="dialog" aria-modal="false" aria-labelledby="tour-title">
      <div class="tour-kicker"><Sparkles :size="16"/> LET'S GET STARTED <span>{{tourStep+1}} / {{tourSteps.length}}</span></div>
      <h2 id="tour-title">{{tourCurrent.title}}</h2><p>{{tourCurrent.body}}</p>
      <div class="tour-progress"><span v-for="(_,i) in tourSteps" :key="i" :class="{filled:i<=tourStep}"></span></div>
      <div class="tour-actions"><button class="btn small" @click="skipTour">Skip tour</button><button class="btn primary small" @click="tourStep===tourSteps.length-1?finishTour():nextTour()">{{tourStep===tourSteps.length-1?'Finish':'Next step'}} <ChevronRight :size="15"/></button></div>
      <small>You can click the highlighted control, or use Next step. Replay this tour anytime with the ? in the header.</small>
    </div>
  </div>
  <div v-if="canEdit && printingProduct && features.printHistory" class="modal-backdrop" @click.self="printingProduct=null"><form class="modal" @submit.prevent="recordPrintV24"><div class="modal-head"><div><h2>Record print run</h2><p>{{printingProduct.name}} · compare estimates with actual consumption</p></div><button type="button" class="icon-button" @click="printingProduct=null"><X :size="20"/></button></div><div class="field-grid"><div class="field"><label>Product variant</label><select v-model="printVariantId" @change="printSpoolSelections={};resetActualPrint()"><option v-for="v in variantList(printingProduct)" :key="v.id" :value="v.id">{{v.name}}</option></select></div><div class="field"><label>Units printed</label><input type="number" min="1" max="100000" step="1" v-model.number="printCount" @change="resetActualPrint()" required/></div></div><div class="field"><label>Result</label><select v-model="printDraft.success"><option :value="true">Successful</option><option :value="false">Failed / wasted</option></select></div><div class="field-grid"><div class="field"><label>Actual hours (total run)</label><input type="number" min="0" step="1" v-model.number="printDraft.actualHours" required/></div><div class="field"><label>Actual minutes</label><input type="number" min="0" max="59" step="1" v-model.number="printDraft.actualMinutes" required/></div></div><div v-for="req in printRequirements" :key="req.filamentId" class="field"><label>{{req.name}} — estimated {{req.grams.toFixed(1)}}g</label><input type="number" min="0" step="0.01" v-model.number="printActualRows[req.filamentId]" required placeholder="Actual grams consumed"/><select v-if="features.inventory && printDraft.deductStock" v-model="printSpoolSelections[req.filamentId]" :required="num(printActualRows[req.filamentId])>0"><option value="">Choose spool for deduction</option><option v-for="sp in state.spools.filter(sp=>sp.filamentId===req.filamentId)" :key="sp.id" :value="sp.id">{{sp.label}} · {{sp.remainingGrams}}g available</option></select></div><label v-if="features.inventory" class="field"><span><input type="checkbox" v-model="printDraft.deductStock"/> Deduct actual consumption from spool inventory</span></label><div class="field"><label>Notes (optional)</label><input v-model="printDraft.note" placeholder="Print settings, failure reason, etc."/></div><p class="hint">Actual material and duration are recorded as historical snapshots. Failed prints count toward waste; recording a sale does not deduct filament.</p><div class="modal-actions"><button type="button" class="btn" @click="printingProduct=null">Cancel</button><button type="submit" class="btn primary">Record print run</button></div></form></div>

  <div v-if="saleProduct && features.sales" class="modal-backdrop" @click.self="saleProduct=null"><form class="modal" @submit.prevent="recordSale"><div class="modal-head"><div><h2>Record sale</h2><p>{{saleProduct.name}} · record an actual sale, not a quote</p></div><button type="button" class="icon-button" @click="saleProduct=null"><X :size="20"/></button></div><div class="field-grid"><div class="field"><label>Quantity sold</label><input required type="number" min="1" step="1" v-model.number="saleDraft.quantity"/></div><div class="field"><label>Sale price per item</label><input required type="number" min="0" step="0.01" v-model.number="saleDraft.unitPrice"/></div></div><div v-if="variantList(saleProduct).length>1" class="field"><label>Product variant</label><select v-model="selectedVariantId" @change="saleDraft.unitPrice=variantFor(saleProduct,selectedVariantId).price"><option v-for="v in variantList(saleProduct)" :key="v.id" :value="v.id">{{v.name}} — {{money(v.price)}}</option></select></div><div class="field"><label>Date</label><input required type="date" v-model="saleDraft.date"/></div><div class="field"><label>Notes (optional)</label><input v-model="saleDraft.note" placeholder="Order reference or customer"/></div><div class="info-box"><Info :size="16"/>The sale records its price and estimated unit cost today. Future material price changes won't rewrite your sales history.</div><div class="modal-actions"><button type="button" class="btn" @click="saleProduct=null">Cancel</button><button type="submit" class="btn primary">Record sale</button></div></form></div>
  <div v-if="notification" class="toast"><Check :size="17"/>{{notification}}</div>
  <div v-if="canEdit && editingProduct" class="modal-backdrop" @click.self="editingProduct=null"><form class="modal" @submit.prevent="saveProduct"><div class="modal-head"><div><h2>Saved product</h2><p>Reusable design or client print</p></div><button type="button" class="icon-button" @click="editingProduct=null"><X :size="20"/></button></div><div class="field-grid"><div class="field"><label>Product name *</label><input required v-model="editingProduct.name" placeholder="e.g. Custom phone stand"/></div><div class="field"><label>SKU / reference</label><input v-model="editingProduct.sku" placeholder="Optional"/></div></div><div class="field"><label>Description</label><input v-model="editingProduct.description" placeholder="What is this product?"/></div><div class="field-grid"><div class="field"><label>Customer (optional)</label><input v-model="editingProduct.customer" placeholder="Client name"/></div><div class="field"><label>Status</label><select v-model="editingProduct.status"><option>Active</option><option>Archived</option><option>Prototype</option></select></div></div><div class="field-grid"><div class="field"><label>Filament</label><select v-model="editingProduct.filamentId"><option value="">Not selected</option><option v-for="f in state.filaments" :key="f.id" :value="f.id">{{f.name}}</option></select></div><div class="field"><label>Printer</label><select v-model="editingProduct.printerId"><option value="">Not selected</option><option v-for="p in state.printers" :key="p.id" :value="p.id">{{p.name}}</option></select></div></div><div class="field-grid"><div class="field"><label>Filament (g)</label><input type="number" min="0" step="0.1" v-model.number="editingProduct.grams"/></div><div class="field"><label>Saved selling price</label><input type="number" min="0" step="0.01" v-model.number="editingProduct.price"/></div></div><div class="field"><label>Additional filament colours / types</label><div v-for="(row,i) in editingProduct.filamentUses||[]" :key="i" class="field-grid"><select v-model="row.filamentId"><option v-for="f in state.filaments" :key="f.id" :value="f.id">{{f.name}}</option></select><input type="number" min="0" step="0.1" v-model.number="row.grams" aria-label="Filament grams"/><button type="button" class="btn small" @click="editingProduct.filamentUses.splice(i,1)">Remove</button></div><button type="button" class="btn small" @click="(editingProduct.filamentUses ||= [{filamentId:editingProduct.filamentId,grams:editingProduct.grams}]).push({filamentId:state.filaments[0]?.id||'',grams:0})">Add filament</button></div><div class="field-grid"><div class="field"><label>Print hours</label><input type="number" min="0" step="1" v-model.number="editingProduct.hours"/></div><div class="field"><label>Print minutes</label><input type="number" min="0" step="1" v-model.number="editingProduct.minutes"/></div></div><div v-if="features.advancedCosting" class="variant-editor"><div class="card-heading"><h3>Product variants & materials</h3><button type="button" class="btn small" @click="addVariant">Add variant</button></div><p class="hint">Without variants, the product's standard settings above are used. Each variant has its own costs and price.</p><div v-for="(v,vi) in editingProduct.variants||[]" :key="v.id" class="variant-row"><div class="field-grid"><div class="field"><label>Variant name</label><input v-model="v.name" required/></div><div class="field"><label>Selling price</label><input type="number" min="0" step="0.01" v-model.number="v.price"/></div></div><div class="field-grid"><div class="field"><label>Filament</label><select v-model="v.filamentId"><option v-for="f in state.filaments" :key="f.id" :value="f.id">{{f.name}}</option></select></div><div class="field"><label>Printer</label><select v-model="v.printerId"><option v-for="r in state.printers" :key="r.id" :value="r.id">{{r.name}}</option></select></div></div><div class="field-grid"><div class="field"><label>Material (g)</label><input type="number" min="0" v-model.number="v.grams"/></div><div class="field"><label>Hours</label><input type="number" min="0" v-model.number="v.hours"/></div><div class="field"><label>Minutes</label><input type="number" min="0" v-model.number="v.minutes"/></div><div class="field"><label>Packaging / unit</label><input type="number" min="0" step="0.01" v-model.number="v.packagingCost"/></div><div class="field"><label>Maintenance / unit</label><input type="number" min="0" step="0.01" v-model.number="v.maintenanceCost"/></div></div><h4>Filament colours / types</h4><p class="hint">Leave this empty to use the single filament above. Each material contributes to the price and stock deduction.</p><div v-for="(row,ri) in v.filamentUses||[]" :key="ri" class="field-grid"><select v-model="row.filamentId"><option v-for="f in state.filaments" :key="f.id" :value="f.id">{{f.name}}</option></select><input type="number" min="0" step="0.1" v-model.number="row.grams" aria-label="Material grams"/><button type="button" class="btn small" @click="v.filamentUses.splice(ri,1)">Remove</button></div><button type="button" class="btn small" @click="(v.filamentUses ||= []).push({filamentId:state.filaments[0]?.id||'',grams:0})">Add filament colour / type</button><h4>Additional components (bill of materials)</h4><div v-for="(m,mi) in v.materials||[]" :key="m.id" class="field-grid"><input aria-label="Component name" v-model="m.name" placeholder="e.g. Magnet"/><input aria-label="Quantity" type="number" min="0" step="1" v-model.number="m.quantity"/><input aria-label="Unit cost" type="number" min="0" step="0.01" v-model.number="m.unitCost"/><button type="button" class="btn small" @click="v.materials.splice(mi,1)">Remove</button></div><button type="button" class="btn small" @click="addMaterial(v)">Add component</button><p>Live cost {{money(costOfVariant(editingProduct,v)||0)}} · margin {{v.price?((v.price-(costOfVariant(editingProduct,v)||0))/v.price*100).toFixed(1):'0'}}%</p><button type="button" class="btn small" @click="editingProduct.variants.splice(vi,1)">Delete variant</button></div></div><div class="field"><label>Notes</label><input v-model="editingProduct.notes" placeholder="Finishing or production notes"/></div><div class="modal-actions"><button type="button" class="btn" @click="editingProduct=null">Cancel</button><button type="submit" class="btn primary">Save product</button></div></form></div>
<div v-if="canEdit && editingFilament" class="modal-backdrop" @click.self="editingFilament=null"><form class="modal" @submit.prevent="saveFilament"><div class="modal-head"><div><h2>{{state.filaments.some(f=>f.id===editingFilament.id)?'Edit filament':'Add filament'}}</h2><p>Material pricing details</p></div><button type="button" class="icon-button" @click="editingFilament=null"><X :size="20"/></button></div><div class="field-grid"><div class="field"><label>Filament name *</label><input v-model="editingFilament.name" required placeholder="e.g. PLA Matte"/></div><div class="field"><label>Brand</label><input v-model="editingFilament.brand" placeholder="e.g. eSUN"/></div></div><div class="field-grid"><div class="field"><label>Material type</label><select v-model="editingFilament.material"><option v-for="m in ['PLA','PLA+','PETG','ABS','ASA','TPU','Nylon','PC','Other']" :key="m">{{m}}</option></select></div><div class="field"><label>Colour / variant</label><input v-model="editingFilament.colour" placeholder="e.g. Matte black"/></div></div><div class="field"><label>Price per kilogram</label><input type="number" min="0" step="0.01" v-model.number="editingFilament.price"/></div><div class="field"><label>Purchase link</label><input type="url" v-model="editingFilament.url" placeholder="https://..."/></div><div v-if="features.inventory" class="field-grid inventory-editor"><div class="field"><label>Stock remaining (g)</label><input type="number" min="0" step="1" v-model.number="editingFilament.stockGrams"/></div><div class="field"><label>Low stock warning (g)</label><input type="number" min="0" step="1" v-model.number="editingFilament.lowStockGrams"/></div></div><div class="modal-actions"><button type="button" class="btn" @click="editingFilament=null">Cancel</button><button class="btn primary" type="submit">Save filament</button></div></form></div>
  <div v-if="canEdit && editingPrinter" class="modal-backdrop" @click.self="editingPrinter=null"><form class="modal" @submit.prevent="savePrinter"><div class="modal-head"><div><h2>{{state.printers.some(p=>p.id===editingPrinter.id)?'Edit printer':'Add printer'}}</h2><p>Printer-specific cost profile</p></div><button type="button" class="icon-button" @click="editingPrinter=null"><X :size="20"/></button></div><div class="field"><label>Printer name / nickname *</label><input v-model="editingPrinter.name" required placeholder="e.g. Workshop P1S #1"/></div><div class="field-grid"><div class="field"><label>Brand</label><select v-model="editingPrinter.brand" @change="editingPrinter.series='';editingPrinter.model=''"><option value="">Choose brand</option><option v-for="brand in printerBrands" :key="brand">{{brand}}</option></select></div><div class="field"><label>Series</label><select v-model="editingPrinter.series" @change="editingPrinter.model=''"><option value="">Choose series</option><option v-for="series in printerSeries" :key="series">{{series}}</option></select></div><div class="field"><label>Model</label><select v-model="editingPrinter.model" @change="selectPrinterModel"><option value="">Choose model</option><option v-for="model in printerModels" :key="model">{{model}}</option></select></div></div><p class="hint">{{catalogLoading?'Loading printer catalogue…':catalogError?'Catalogue unavailable: '+catalogError:'Catalogue can be refreshed on the server without a PrintQuote release.'}} Enter your own nickname above.</p><div class="field-grid"><div class="field"><label>Technology</label><select v-model="editingPrinter.technology"><option>FDM</option><option>Resin</option><option>Other</option></select></div><div class="field"><label>Average power consumption (W)</label><input type="number" min="0" step="1" v-model.number="editingPrinter.power"/></div></div><div class="field-grid"><div class="field"><label>Setup time / job (min)</label><input type="number" min="0" step="1" v-model.number="editingPrinter.setupMinutes"/></div><div class="field"><label>Post-processing / item (min)</label><input type="number" min="0" step="1" v-model.number="editingPrinter.postMinutes"/></div></div><div class="field"><label>Machine overhead / print hour</label><input type="number" min="0" step="0.01" v-model.number="editingPrinter.overheadRate"/></div><div class="info-box"><Info :size="17"/>Machine overhead can account for wear, depreciation, servicing and consumables. Enter your own hourly estimate.</div><div class="modal-actions"><button type="button" class="btn" @click="editingPrinter=null">Cancel</button><button class="btn primary" type="submit">Save printer</button></div></form></div>
</div>
</template>
